export interface GroundingChunk {
  web?: {
    uri: string;
    title: string;
  };
}

export interface AnalysisData {
  overallReception: string;
  targetAudience: string;
  antiTargetAudience: string;
  problematicElements: string;
  dependencies: string;
  rawText: string;
  sources: { title: string; uri: string }[];
}

export interface MovieRecommendation {
  title: string;
  year: string;
  reason: string;
  suitability: string;
}

export type AnalysisResult = 
  | { type: 'SUCCESS'; data: AnalysisData }
  | { type: 'AMBIGUOUS'; candidates: string[] }
  | { type: 'NOT_FOUND' };

export enum LoadingStage {
  IDLE = 'IDLE',
  SEARCHING = 'SEARCHING',
  ANALYZING = 'ANALYZING',
  RECOMMENDING = 'RECOMMENDING',
  COMPLETED = 'COMPLETED',
  ERROR = 'ERROR'
}

export interface RecommendationRequirements {
  genres: string[];
  company: string;
  pacing: string;
  customDescription: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult, MovieRecommendation, RecommendationRequirements } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const ANALYSIS_SYSTEM_INSTRUCTION = `
You are a film expert and "movie night" curator. Your task is to analyze a movie for a group setting. 

STEP 1: IDENTIFICATION & DISAMBIGUATION
First, determine if the movie exists and if the user's query is specific enough.
- If the movie DOES NOT EXIST, output: VERDICT_STATUS: NOT_FOUND
- If the title is AMBIGUOUS, output: VERDICT_STATUS: AMBIGUOUS followed by a JSON array of strings with the specific titles and years.
- If clear, proceed.

STEP 2: ANALYSIS
Search IMDb, Letterboxd, Metacritic, and Wikipedia (specifically the Reception/Critical Response sections).

VERDICT FORMAT:
## OVERALL RECEPTION
- Brief summary of critical consensus and audience sentiment. Include Wikipedia reception highlights.

## TARGET AUDIENCE
- Describe who this movie is for.

## NOT FOR SPECIFICALLY
- Describe the audience for whom this movie is a specific "red flag" (use ☹️ in descriptions).

## PROBLEMATIC ELEMENTS
- Detailed scan for triggers, gore, nudity, "brainrot", or confusing plots.

## DEPENDENCIES
- Ordered list of required viewing or "Standalone Movie".
`;

export const analyzeMovie = async (movieQuery: string, includeSpoilers: boolean): Promise<AnalysisResult> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analyze: "${movieQuery}". Spoilers allowed: ${includeSpoilers}.`,
      config: {
        systemInstruction: ANALYSIS_SYSTEM_INSTRUCTION,
        tools: [{ googleSearch: {} }],
      },
    });

    const text = response.text || "";
    if (text.includes("VERDICT_STATUS: NOT_FOUND")) return { type: 'NOT_FOUND' };
    if (text.includes("VERDICT_STATUS: AMBIGUOUS")) {
      const jsonMatch = text.match(/\[.*\]/s);
      return { type: 'AMBIGUOUS', candidates: jsonMatch ? JSON.parse(jsonMatch[0]) : [] };
    }

    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const sources = groundingChunks
      .map((chunk: any) => chunk.web ? { title: chunk.web.title, uri: chunk.web.uri } : null)
      .filter((s: any): s is { title: string; uri: string } => s !== null);

    const clean = (str: string | undefined) => str ? str.trim() : "No specific data found.";

    return {
      type: 'SUCCESS',
      data: {
        overallReception: clean(text.match(/## OVERALL RECEPTION([\s\S]*?)(?=## TARGET AUDIENCE|$)/i)?.[1]),
        targetAudience: clean(text.match(/## TARGET AUDIENCE([\s\S]*?)(?=## NOT FOR SPECIFICALLY|$)/i)?.[1]),
        antiTargetAudience: clean(text.match(/## NOT FOR SPECIFICALLY([\s\S]*?)(?=## PROBLEMATIC ELEMENTS|$)/i)?.[1]),
        problematicElements: clean(text.match(/## PROBLEMATIC ELEMENTS([\s\S]*?)(?=## DEPENDENCIES|$)/i)?.[1]),
        dependencies: clean(text.match(/## DEPENDENCIES([\s\S]*?)(?=$)/i)?.[1]),
        rawText: text,
        sources
      }
    };
  } catch (error) {
    console.error(error);
    throw error;
  }
};

export const getRecommendations = async (reqs: RecommendationRequirements): Promise<MovieRecommendation[]> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Suggest 5 movies based on:
      Genres: ${reqs.genres.join(', ')}
      Watching with: ${reqs.company}
      Pacing: ${reqs.pacing}
      Extra details: ${reqs.customDescription || 'None provided'}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              year: { type: Type.STRING },
              reason: { type: Type.STRING, description: "Why it matches user's specific mood and pacing requirements" },
              suitability: { type: Type.STRING, description: "One sentence on suitability for the mentioned 'company'" }
            },
            required: ['title', 'year', 'reason', 'suitability']
          }
        },
        tools: [{ googleSearch: {} }]
      }
    });

    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("Recommendation Error:", error);
    throw error;
  }
};

import React, { useState } from 'react';
import { RecommendationRequirements, MovieRecommendation } from '../types';

interface RecommendationTabProps {
  onGetRecommendations: (reqs: RecommendationRequirements) => void;
  results: MovieRecommendation[] | null;
  isLoading: boolean;
  onReset: () => void;
}

const GENRES = ["Action", "Comedy", "Horror", "Thriller", "Sci-Fi", "Drama", "Romance", "Documentary", "Animated", "Mystery"];
const COMPANIES = ["Solo", "Date Night", "Family (Kids)", "Friends (Rowdy)", "Parents/Seniors"];
const PACING = ["Fast & Furious", "Balanced", "Slow Burn"];

export const RecommendationTab: React.FC<RecommendationTabProps> = ({ onGetRecommendations, results, isLoading, onReset }) => {
  const [formData, setFormData] = useState<RecommendationRequirements>({
    genres: [],
    company: 'Solo',
    pacing: 'Balanced',
    customDescription: ''
  });

  const toggleGenre = (genre: string) => {
    setFormData(prev => ({
      ...prev,
      genres: prev.genres.includes(genre) 
        ? prev.genres.filter(g => g !== genre)
        : [...prev.genres, genre]
    }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onGetRecommendations(formData);
  };

  if (results) {
    return (
      <div className="max-w-4xl mx-auto w-full pb-20 animate-fade-in">
        <div className="flex justify-between items-center mb-8 border-b border-gray-800 pb-4">
          <h2 className="text-2xl font-bold text-white">Top 5 Curated Picks 🍿</h2>
          <button onClick={onReset} className="text-sm text-gray-400 hover:text-white underline">Start Over</button>
        </div>
        <div className="grid gap-6">
          {results.map((movie, idx) => (
            <div key={idx} className="bg-cine-gray/30 border border-gray-800 rounded-xl p-6 hover:border-cine-accent transition-all duration-300">
              <div className="flex justify-between items-start mb-3">
                <h3 className="text-xl font-bold text-white">{movie.title} <span className="text-gray-500 text-base">({movie.year})</span></h3>
                <span className="bg-cine-accent/20 text-cine-accent text-[10px] uppercase font-bold px-2 py-1 rounded">Recommendation #{idx + 1}</span>
              </div>
              <p className="text-gray-300 mb-4 leading-relaxed"><strong className="text-cine-gold uppercase text-xs tracking-wider block mb-1">Why it matches:</strong> {movie.reason}</p>
              <div className="bg-cine-black/50 rounded-lg p-3 border border-gray-800/50">
                <p className="text-sm text-gray-400 italic">
                   <span className="text-gray-500 font-bold not-italic mr-2">VIBE CHECK:</span>
                   {movie.suitability}
                </p>
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto w-full animate-fade-in pb-20">
      <form onSubmit={handleSubmit} className="bg-cine-dark border border-gray-800 rounded-2xl p-8 shadow-2xl">
        <h2 className="text-2xl font-bold text-white mb-6 text-center">Describe Your Perfect Night</h2>

        {/* Genre Select */}
        <div className="mb-8">
          <label className="block text-gray-400 text-sm font-bold mb-3 uppercase tracking-wider">Which vibes are we feeling?</label>
          <div className="flex flex-wrap gap-2">
            {GENRES.map(genre => (
              <button
                key={genre}
                type="button"
                onClick={() => toggleGenre(genre)}
                className={`px-3 py-1.5 rounded-full text-xs font-medium transition-all ${
                  formData.genres.includes(genre) 
                    ? 'bg-cine-accent text-white shadow-lg shadow-cine-accent/20' 
                    : 'bg-gray-800 text-gray-400 hover:bg-gray-700'
                }`}
              >
                {genre}
              </button>
            ))}
          </div>
        </div>

        {/* Company Select */}
        <div className="mb-8">
          <label className="block text-gray-400 text-sm font-bold mb-3 uppercase tracking-wider">Who's on the couch?</label>
          <select 
            value={formData.company}
            onChange={(e) => setFormData(p => ({...p, company: e.target.value}))}
            className="w-full bg-cine-black border border-gray-700 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-cine-accent transition-colors"
          >
            {COMPANIES.map(c => <option key={c} value={c}>{c}</option>)}
          </select>
        </div>

        {/* Pacing Select */}
        <div className="mb-8">
          <label className="block text-gray-400 text-sm font-bold mb-3 uppercase tracking-wider">How fast should it move?</label>
          <div className="grid grid-cols-3 gap-3">
            {PACING.map(p => (
              <button
                key={p}
                type="button"
                onClick={() => setFormData(prev => ({...prev, pacing: p}))}
                className={`py-3 rounded-lg text-xs font-bold border transition-all ${
                  formData.pacing === p 
                    ? 'border-cine-gold text-cine-gold bg-cine-gold/5' 
                    : 'border-gray-800 text-gray-500 hover:border-gray-600'
                }`}
              >
                {p}
              </button>
            ))}
          </div>
        </div>

        {/* Custom Description */}
        <div className="mb-8">
          <label className="block text-gray-400 text-sm font-bold mb-3 uppercase tracking-wider">Anything else? (Optional)</label>
          <textarea
            className="w-full bg-cine-black border border-gray-700 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-cine-accent transition-colors h-24 resize-none"
            placeholder="e.g. 'Looking for 90s vibes', 'strictly no animal cruelty', 'something mind-bending'..."
            value={formData.customDescription}
            onChange={(e) => setFormData(p => ({...p, customDescription: e.target.value}))}
          />
        </div>

        <button
          type="submit"
          disabled={isLoading || formData.genres.length === 0}
          className="w-full bg-gradient-to-r from-cine-accent to-red-600 py-4 rounded-xl font-bold text-white shadow-xl hover:scale-[1.02] active:scale-[0.98] transition-all disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {isLoading ? 'Curating Your List...' : 'Get Top 5 Recommendations'}
        </button>
      </form>
    </div>
  );
};

import React, { useState } from 'react';
import { Hero } from './components/Hero';
import { SearchBar } from './components/SearchBar';
import { AnalysisResult } from './components/AnalysisResult';
import { DisambiguationOptions } from './components/DisambiguationOptions';
import { RecommendationTab } from './components/RecommendationTab';
import { analyzeMovie, getRecommendations } from './services/geminiService';
import { AnalysisData, LoadingStage, MovieRecommendation, RecommendationRequirements } from './types';

type Tab = 'ANALYZER' | 'RECOMMENDER';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>('ANALYZER');
  const [loadingStage, setLoadingStage] = useState<LoadingStage>(LoadingStage.IDLE);
  const [analysisData, setAnalysisData] = useState<AnalysisData | null>(null);
  const [recResults, setRecResults] = useState<MovieRecommendation[] | null>(null);
  const [candidates, setCandidates] = useState<string[]>([]);
  const [currentMovie, setCurrentMovie] = useState<string>('');
  const [includeSpoilers, setIncludeSpoilers] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  const handleSearch = async (query: string, spoilers: boolean) => {
    setLoadingStage(LoadingStage.SEARCHING);
    setAnalysisData(null);
    setCandidates([]);
    setError(null);
    setCurrentMovie(query);
    setIncludeSpoilers(spoilers);

    try {
      const stageTimer = setTimeout(() => setLoadingStage(LoadingStage.ANALYZING), 1000);
      const result = await analyzeMovie(query, spoilers);
      clearTimeout(stageTimer);

      if (result.type === 'SUCCESS') {
        setAnalysisData(result.data);
        setLoadingStage(LoadingStage.COMPLETED);
      } else if (result.type === 'AMBIGUOUS') {
        setCandidates(result.candidates);
        setLoadingStage(LoadingStage.COMPLETED);
      } else if (result.type === 'NOT_FOUND') {
        setError("Movie not found. Try adding the year!");
        setLoadingStage(LoadingStage.ERROR);
      }
    } catch (err) {
      setError("Failed to analyze. Try again later.");
      setLoadingStage(LoadingStage.ERROR);
    }
  };

  const handleGetRecommendations = async (reqs: RecommendationRequirements) => {
    setLoadingStage(LoadingStage.RECOMMENDING);
    setRecResults(null);
    setError(null);
    try {
      const results = await getRecommendations(reqs);
      setRecResults(results);
      setLoadingStage(LoadingStage.COMPLETED);
    } catch (err) {
      setError("Failed to get recommendations.");
      setLoadingStage(LoadingStage.ERROR);
    }
  };

  const handleReset = () => {
    setAnalysisData(null);
    setRecResults(null);
    setCandidates([]);
    setLoadingStage(LoadingStage.IDLE);
    setCurrentMovie('');
    setError(null);
  };

  const isShowingResults = !!analysisData || !!recResults || candidates.length > 0;

  return (
    <div className="min-h-screen bg-cine-black text-white selection:bg-cine-accent flex flex-col font-sans">
      <div className="fixed top-0 left-0 w-full h-full overflow-hidden -z-10 pointer-events-none">
        <div className="absolute -top-[20%] -left-[10%] w-[50%] h-[50%] bg-purple-900/10 rounded-full blur-[120px]"></div>
        <div className="absolute top-[20%] -right-[10%] w-[40%] h-[40%] bg-red-900/10 rounded-full blur-[120px]"></div>
      </div>

      {/* Tab Switcher */}
      <div className="container mx-auto px-4 mt-8">
        <div className="flex justify-center border-b border-gray-800 gap-8">
          <button 
            onClick={() => { setActiveTab('ANALYZER'); handleReset(); }}
            className={`pb-4 text-sm font-bold uppercase tracking-widest transition-all relative ${activeTab === 'ANALYZER' ? 'text-cine-accent' : 'text-gray-500 hover:text-gray-300'}`}
          >
            Content Guard
            {activeTab === 'ANALYZER' && <div className="absolute bottom-0 left-0 w-full h-0.5 bg-cine-accent shadow-[0_0_10px_rgba(229,9,20,0.5)]"></div>}
          </button>
          <button 
            onClick={() => { setActiveTab('RECOMMENDER'); handleReset(); }}
            className={`pb-4 text-sm font-bold uppercase tracking-widest transition-all relative ${activeTab === 'RECOMMENDER' ? 'text-cine-accent' : 'text-gray-500 hover:text-gray-300'}`}
          >
            Mood Matcher
            {activeTab === 'RECOMMENDER' && <div className="absolute bottom-0 left-0 w-full h-0.5 bg-cine-accent shadow-[0_0_10px_rgba(229,9,20,0.5)]"></div>}
          </button>
        </div>
      </div>

      <main className="flex-grow container mx-auto px-4 sm:px-6 relative z-10 pt-10">

        {activeTab === 'ANALYZER' ? (
          <>
            {!isShowingResults && loadingStage === LoadingStage.IDLE && <Hero />}
            <div className={`transition-all duration-500 ${isShowingResults || loadingStage !== LoadingStage.IDLE ? 'mb-8' : 'pb-10'}`}>
               {isShowingResults ? (
                 <div className="flex justify-between items-center max-w-4xl mx-auto mb-6 bg-cine-gray/20 p-4 rounded-lg backdrop-blur-sm border border-gray-800">
                    <h1 className="text-xl font-bold text-white">Analysis <span className="text-cine-accent">Report</span></h1>
                    <button onClick={handleReset} className="text-xs text-gray-400 hover:text-white underline">New Analysis</button>
                 </div>
               ) : (
                 <SearchBar onSearch={handleSearch} isLoading={loadingStage === LoadingStage.SEARCHING || loadingStage === LoadingStage.ANALYZING} />
               )}
            </div>

            {loadingStage === LoadingStage.SEARCHING || loadingStage === LoadingStage.ANALYZING ? (
              <div className="flex flex-col items-center justify-center py-20 animate-pulse">
                 <div className="w-16 h-16 border-4 border-cine-gray border-t-cine-accent rounded-full animate-spin mb-6"></div>
                 <p className="text-xl font-medium text-gray-300">{loadingStage === LoadingStage.SEARCHING ? 'Finding Movie...' : 'Scanning for Content Risks...'}</p>
              </div>
            ) : null}

            {candidates.length > 0 && <DisambiguationOptions candidates={candidates} onSelect={(m) => handleSearch(m, includeSpoilers)} onCancel={handleReset} />}
            {analysisData && <AnalysisResult data={analysisData} movieTitle={currentMovie} onReset={handleReset} />}
          </>
        ) : (
          <>
            <div className="text-center mb-10">
               <h1 className="text-3xl md:text-5xl font-black text-white mb-2">The Mood Matcher</h1>
               <p className="text-gray-400">Tell us what you want, we'll find the perfect match.</p>
            </div>
            <RecommendationTab 
              onGetRecommendations={handleGetRecommendations} 
              results={recResults} 
              isLoading={loadingStage === LoadingStage.RECOMMENDING}
              onReset={handleReset}
            />
          </>
        )}

        {error && (
          <div className="max-w-2xl mx-auto bg-red-900/10 border border-red-500/30 rounded-lg p-6 text-center animate-fade-in my-8">
            <p className="text-red-400">{error}</p>
          </div>
        )}
      </main>

      <footer className="py-8 text-center text-gray-600 text-xs tracking-widest uppercase">
        © {new Date().getFullYear()} Movie Night Friendly • Built with Gemini
      </footer>
    </div>
  );
};

export default App;

