import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult, MovieRecommendation, RecommendationRequirements } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const ANALYSIS_SYSTEM_INSTRUCTION = `
You are a film expert and "movie night" curator. Your task is to analyze a movie for a group setting. 

STEP 1: IDENTIFICATION & DISAMBIGUATION
First, determine if the movie exists and if the user's query is specific enough.
- If the movie DOES NOT EXIST, output: VERDICT_STATUS: NOT_FOUND
- If the title is AMBIGUOUS, output: VERDICT_STATUS: AMBIGUOUS followed by a JSON array of strings with the specific titles and years.
- If clear, proceed.

STEP 2: ANALYSIS
Search IMDb, Letterboxd, Metacritic, and Wikipedia (specifically the Reception/Critical Response sections).

VERDICT FORMAT:
## OVERALL RECEPTION
- Brief summary of critical consensus and audience sentiment. Include Wikipedia reception highlights.

## TARGET AUDIENCE
- Describe who this movie is for.

## NOT FOR SPECIFICALLY
- Describe the audience for whom this movie is a specific "red flag" (use ☹️ in descriptions).

## PROBLEMATIC ELEMENTS
- Detailed scan for triggers, gore, nudity, "brainrot", or confusing plots.

## DEPENDENCIES
- Ordered list of required viewing or "Standalone Movie".
`;

export const analyzeMovie = async (movieQuery: string, includeSpoilers: boolean): Promise<AnalysisResult> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analyze: "${movieQuery}". Spoilers allowed: ${includeSpoilers}.`,
      config: {
        systemInstruction: ANALYSIS_SYSTEM_INSTRUCTION,
        tools: [{ googleSearch: {} }],
      },
    });

    const text = response.text || "";
    if (text.includes("VERDICT_STATUS: NOT_FOUND")) return { type: 'NOT_FOUND' };
    if (text.includes("VERDICT_STATUS: AMBIGUOUS")) {
      const jsonMatch = text.match(/\[.*\]/s);
      return { type: 'AMBIGUOUS', candidates: jsonMatch ? JSON.parse(jsonMatch[0]) : [] };
    }

    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const sources = groundingChunks
      .map((chunk: any) => chunk.web ? { title: chunk.web.title, uri: chunk.web.uri } : null)
      .filter((s: any): s is { title: string; uri: string } => s !== null);

    const clean = (str: string | undefined) => str ? str.trim() : "No specific data found.";

    return {
      type: 'SUCCESS',
      data: {
        overallReception: clean(text.match(/## OVERALL RECEPTION([\s\S]*?)(?=## TARGET AUDIENCE|$)/i)?.[1]),
        targetAudience: clean(text.match(/## TARGET AUDIENCE([\s\S]*?)(?=## NOT FOR SPECIFICALLY|$)/i)?.[1]),
        antiTargetAudience: clean(text.match(/## NOT FOR SPECIFICALLY([\s\S]*?)(?=## PROBLEMATIC ELEMENTS|$)/i)?.[1]),
        problematicElements: clean(text.match(/## PROBLEMATIC ELEMENTS([\s\S]*?)(?=## DEPENDENCIES|$)/i)?.[1]),
        dependencies: clean(text.match(/## DEPENDENCIES([\s\S]*?)(?=$)/i)?.[1]),
        rawText: text,
        sources
      }
    };
  } catch (error) {
    console.error(error);
    throw error;
  }
};

export const getRecommendations = async (reqs: RecommendationRequirements): Promise<MovieRecommendation[]> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Suggest 5 movies based on:
      Genres: ${reqs.genres.join(', ')}
      Watching with: ${reqs.company}
      Pacing: ${reqs.pacing}
      Preferred Language: ${reqs.language}
      Extra details: ${reqs.customDescription || 'None provided'}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              year: { type: Type.STRING },
              reason: { type: Type.STRING, description: "Why it matches user's specific mood and pacing requirements" },
              suitability: { type: Type.STRING, description: "One sentence on suitability for the mentioned 'company'" }
            },
            required: ['title', 'year', 'reason', 'suitability']
          }
        },
        tools: [{ googleSearch: {} }]
      }
    });

    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("Recommendation Error:", error);
    throw error;
  }
};

