import React, { useState, useRef, useEffect } from 'react';
import { RecommendationRequirements, MovieRecommendation } from '../types';

interface RecommendationTabProps {
  onGetRecommendations: (reqs: RecommendationRequirements) => void;
  results: MovieRecommendation[] | null;
  isLoading: boolean;
  onReset: () => void;
}

const GENRES = ["Action", "Comedy", "Horror", "Thriller", "Sci-Fi", "Drama", "Romance", "Documentary", "Animated", "Mystery"];
const COMPANIES = ["Solo", "Family", "Friends", "Cinephiles/Critics"];
const PACING = ["Fast & Furious", "Balanced", "Slow Burn"];
const LANGUAGES = [
  "Any Language",
  "English",
  "French",
  "German",
  "Hindi",
  "Italian",
  "Japanese",
  "Kannada",
  "Korean",
  "Malayalam",
  "Mandarin",
  "Portuguese",
  "Spanish",
  "Tamil",
  "Telugu"
].sort((a, b) => a === "Any Language" ? -1 : b === "Any Language" ? 1 : a.localeCompare(b));

export const RecommendationTab: React.FC<RecommendationTabProps> = ({ onGetRecommendations, results, isLoading, onReset }) => {
  const [formData, setFormData] = useState<RecommendationRequirements>({
    genres: [],
    company: 'Solo',
    pacing: 'Balanced',
    languages: ['Any Language'],
    customDescription: ''
  });

  const [watchedIndices, setWatchedIndices] = useState<Set<number>>(new Set());
  const [isLangDropdownOpen, setIsLangDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsLangDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const toggleGenre = (genre: string) => {
    setFormData(prev => ({
      ...prev,
      genres: prev.genres.includes(genre) 
        ? prev.genres.filter(g => g !== genre)
        : [...prev.genres, genre]
    }));
  };

  const toggleLanguage = (lang: string) => {
    setFormData(prev => {
      let newLangs = [...prev.languages];

      if (lang === "Any Language") {
        return { ...prev, languages: ["Any Language"] };
      }

      // If user clicks a specific language
      if (newLangs.includes(lang)) {
        newLangs = newLangs.filter(l => l !== lang);
        // If empty, default back to Any
        if (newLangs.length === 0) newLangs = ["Any Language"];
      } else {
        // Remove "Any Language" if it exists when adding a specific one
        newLangs = newLangs.filter(l => l !== "Any Language");
        newLangs.push(lang);
      }

      return { ...prev, languages: newLangs };
    });
  };

  const handleWatched = (idx: number) => {
    setWatchedIndices(prev => {
      const next = new Set(prev);
      next.add(idx);
      return next;
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setWatchedIndices(new Set());
    onGetRecommendations(formData);
  };

  if (results) {
    return (
      <div className="max-w-4xl mx-auto w-full pb-20 animate-fade-in">
        <div className="flex justify-between items-center mb-8 border-b border-gray-800 pb-4">
          <h2 className="text-2xl font-bold text-white">Top 5 Curated Picks 🍿</h2>
          <button onClick={onReset} className="text-sm text-gray-400 hover:text-white underline">Start Over</button>
        </div>
        <div className="grid gap-6">
          {results.map((movie, idx) => {
            const isWatched = watchedIndices.has(idx);
            return (
              <div key={idx} className="bg-cine-gray/30 border border-gray-800 rounded-xl p-6 hover:border-cine-accent transition-all duration-300">
                <div className="flex justify-between items-start mb-3">
                  <h3 className="text-xl font-bold text-white">{movie.title} <span className="text-gray-500 text-base">({movie.year})</span></h3>
                  <span className="bg-cine-accent/20 text-cine-accent text-[10px] uppercase font-bold px-2 py-1 rounded">Recommendation #{idx + 1}</span>
                </div>
                <p className="text-gray-300 mb-4 leading-relaxed"><strong className="text-cine-gold uppercase text-xs tracking-wider block mb-1">Why it matches:</strong> {movie.reason}</p>
                <div className="bg-cine-black/50 rounded-lg p-3 border border-gray-800/50 mb-4">
                  <p className="text-sm text-gray-400 italic">
                     <span className="text-gray-500 font-bold not-italic mr-2">VIBE CHECK:</span>
                     {movie.suitability}
                  </p>
                </div>

                <div className="flex justify-end pt-2">
                  {isWatched ? (
                    <div className="flex items-center gap-2 text-green-500 font-bold text-sm bg-green-500/10 px-4 py-2 rounded-lg border border-green-500/20 animate-fade-in">
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
                      </svg>
                      Watched!
                    </div>
                  ) : (
                    <button 
                      onClick={() => handleWatched(idx)}
                      className="text-xs font-bold text-gray-400 hover:text-white border border-gray-700 hover:border-cine-accent px-4 py-2 rounded-lg transition-all active:scale-95"
                    >
                      I watched this movie
                    </button>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  const selectedLangsLabel = formData.languages.join(', ');

  return (
    <div className="max-w-2xl mx-auto w-full animate-fade-in pb-20">
      <form onSubmit={handleSubmit} className="bg-cine-dark border border-gray-800 rounded-2xl p-8 shadow-2xl">
        <h2 className="text-2xl font-bold text-white mb-6 text-center">Describe Your Perfect Movie</h2>

        {/* Genre Select */}
        <div className="mb-8">
          <label className="block text-gray-400 text-sm font-bold mb-3 uppercase tracking-wider">Which vibes are we feeling?</label>
          <div className="flex flex-wrap gap-2">
            {GENRES.map(genre => (
              <button
                key={genre}
                type="button"
                onClick={() => toggleGenre(genre)}
                className={`px-3 py-1.5 rounded-full text-xs font-medium transition-all ${
                  formData.genres.includes(genre) 
                    ? 'bg-cine-accent text-white shadow-lg shadow-cine-accent/20' 
                    : 'bg-gray-800 text-gray-400 hover:bg-gray-700'
                }`}
              >
                {genre}
              </button>
            ))}
          </div>
        </div>

        {/* Company & Language Row */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
          <div>
            <label className="block text-gray-400 text-sm font-bold mb-3 uppercase tracking-wider">Who's on the couch?</label>
            <select 
              value={formData.company}
              onChange={(e) => setFormData(p => ({...p, company: e.target.value}))}
              className="w-full bg-cine-black border border-gray-700 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-cine-accent transition-colors"
            >
              {COMPANIES.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>

          <div className="relative" ref={dropdownRef}>
            <label className="block text-gray-400 text-sm font-bold mb-3 uppercase tracking-wider">Language Preference</label>
            <button
              type="button"
              onClick={() => setIsLangDropdownOpen(!isLangDropdownOpen)}
              className="w-full bg-cine-black border border-gray-700 rounded-lg px-4 py-3 text-white text-left focus:outline-none focus:border-cine-accent transition-colors flex justify-between items-center"
            >
              <span className="truncate pr-2">
                {selectedLangsLabel}
              </span>
              <svg className={`w-4 h-4 transition-transform ${isLangDropdownOpen ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
              </svg>
            </button>

            {isLangDropdownOpen && (
              <div className="absolute z-50 w-full mt-2 bg-cine-gray border border-gray-700 rounded-lg shadow-2xl max-h-60 overflow-y-auto custom-scrollbar animate-fade-in">
                {LANGUAGES.map(lang => (
                  <button
                    key={lang}
                    type="button"
                    onClick={() => toggleLanguage(lang)}
                    className="w-full flex items-center px-4 py-3 hover:bg-cine-accent/10 text-left transition-colors border-b border-gray-800 last:border-0"
                  >
                    <div className={`w-4 h-4 rounded border flex items-center justify-center mr-3 transition-colors ${
                      formData.languages.includes(lang) ? 'bg-cine-accent border-cine-accent' : 'border-gray-500'
                    }`}>
                      {formData.languages.includes(lang) && (
                        <svg className="w-3 h-3 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
                        </svg>
                      )}
                    </div>
                    <span className={`text-sm ${formData.languages.includes(lang) ? 'text-white' : 'text-gray-400'}`}>
                      {lang}
                    </span>
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Pacing Select */}
        <div className="mb-8">
          <label className="block text-gray-400 text-sm font-bold mb-3 uppercase tracking-wider">How fast should it move?</label>
          <div className="grid grid-cols-3 gap-3">
            {PACING.map(p => (
              <button
                key={p}
                type="button"
                onClick={() => setFormData(prev => ({...prev, pacing: p}))}
                className={`py-3 rounded-lg text-xs font-bold border transition-all ${
                  formData.pacing === p 
                    ? 'border-cine-gold text-cine-gold bg-cine-gold/5' 
                    : 'border-gray-800 text-gray-500 hover:border-gray-600'
                }`}
              >
                {p}
              </button>
            ))}
          </div>
        </div>

        {/* Custom Description */}
        <div className="mb-8">
          <label className="block text-gray-400 text-sm font-bold mb-3 uppercase tracking-wider">Anything else? (Optional)</label>
          <textarea
            className="w-full bg-cine-black border border-gray-700 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-cine-accent transition-colors h-24 resize-none"
            placeholder="e.g. 'Looking for 90s vibes', 'strictly no animal cruelty', 'something mind-bending'..."
            value={formData.customDescription}
            onChange={(e) => setFormData(p => ({...p, customDescription: e.target.value}))}
          />
        </div>

        <button
          type="submit"
          disabled={isLoading || formData.genres.length === 0}
          className="w-full bg-gradient-to-r from-cine-accent to-red-600 py-4 rounded-xl font-bold text-white shadow-xl hover:scale-[1.02] active:scale-[0.98] transition-all disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {isLoading ? 'Curating Your List...' : 'Get Top 5 Recommendations'}
        </button>
      </form>
    </div>
  );
};

