import React, { useState } from 'react';
import { User } from '../types';

interface AuthBoothProps {
  onLogin: (user: User) => void;
}

export const AuthBooth: React.FC<AuthBoothProps> = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [ticketCode, setTicketCode] = useState('');
  const [isNewUser, setIsNewUser] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!username || !ticketCode) return;

    const storedUsers = JSON.parse(localStorage.getItem('cine_vault_users') || '[]');
    let user = storedUsers.find((u: User) => u.username === username);

    if (isNewUser) {
      if (user) {
        alert("This Persona is already taken at the Box Office!");
        return;
      }
      const newUser: User = { username, ticketCode, watchedMovies: [] };
      storedUsers.push(newUser);
      localStorage.setItem('cine_vault_users', JSON.stringify(storedUsers));
      onLogin(newUser);
    } else {
      if (!user || user.ticketCode !== ticketCode) {
        alert("Invalid Ticket Code for this Persona!");
        return;
      }
      onLogin(user);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-cine-black/95 backdrop-blur-xl p-4">
      <div className="relative w-full max-w-md bg-cine-dark border-4 border-cine-gold rounded-3xl overflow-hidden shadow-[0_0_50px_rgba(245,197,24,0.2)]">
        {/* Ticket Header */}
        <div className="bg-cine-gold p-6 text-cine-black text-center">
          <h2 className="text-3xl font-black uppercase tracking-tighter italic">Cine-Vault Ticket</h2>
          <p className="text-[10px] font-bold tracking-[0.2em] uppercase opacity-70">Admit One: Cinema Enthusiast</p>
        </div>

        <div className="p-8">
          <form onSubmit={handleSubmit} className="space-y-6">
            <div>
              <label className="block text-cine-gold text-[10px] font-bold uppercase tracking-widest mb-2">Cine-Persona (Username)</label>
              <input
                type="text"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                className="w-full bg-cine-black border border-gray-800 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-cine-gold transition-colors"
                placeholder="The_Movie_Buff"
              />
            </div>
            <div>
              <label className="block text-cine-gold text-[10px] font-bold uppercase tracking-widest mb-2">Secret Ticket Code (Password)</label>
              <input
                type="password"
                value={ticketCode}
                onChange={(e) => setTicketCode(e.target.value)}
                className="w-full bg-cine-black border border-gray-800 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-cine-gold transition-colors"
                placeholder="Your secret movie title..."
              />
            </div>

            <button
              type="submit"
              className="w-full bg-cine-gold text-cine-black font-black py-4 rounded-xl uppercase tracking-widest hover:scale-[1.02] active:scale-[0.98] transition-all shadow-lg shadow-cine-gold/20"
            >
              {isNewUser ? 'Issue New Ticket' : 'Enter the Vault'}
            </button>
          </form>

          <div className="mt-8 text-center">
            <button 
              onClick={() => setIsNewUser(!isNewUser)}
              className="text-[10px] text-gray-500 uppercase tracking-widest hover:text-cine-gold transition-colors"
            >
              {isNewUser ? 'Already have a ticket? Enter here' : 'New at the Box Office? Get a ticket'}
            </button>
          </div>
        </div>

        {/* Decorative Ticket Punches */}
        <div className="absolute top-1/2 -left-4 w-8 h-8 bg-cine-black/95 rounded-full -translate-y-1/2 border-r border-gray-800"></div>
        <div className="absolute top-1/2 -right-4 w-8 h-8 bg-cine-black/95 rounded-full -translate-y-1/2 border-l border-gray-800"></div>
      </div>
    </div>
  );
};

