import React, { useState, useEffect } from 'react';
import { Hero } from './components/Hero';
import { SearchBar } from './components/SearchBar';
import { AnalysisResult } from './components/AnalysisResult';
import { DisambiguationOptions } from './components/DisambiguationOptions';
import { RecommendationTab } from './components/RecommendationTab';
import { MovieMatcherTab } from './components/MovieMatcherTab';
import { AuthBooth } from './components/AuthBooth';
import { UserProfile } from './components/UserProfile';
import { analyzeMovie, getRecommendations, getSimilarMovies } from './services/geminiService';
import { AnalysisData, LoadingStage, MovieRecommendation, RecommendationRequirements, SimilarityRequest, User } from './types';

type Tab = 'ANALYZER' | 'RECOMMENDER' | 'MATCHER';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>('ANALYZER');
  const [loadingStage, setLoadingStage] = useState<LoadingStage>(LoadingStage.IDLE);
  const [analysisData, setAnalysisData] = useState<AnalysisData | null>(null);
  const [recResults, setRecResults] = useState<MovieRecommendation[] | null>(null);
  const [matcherResults, setMatcherResults] = useState<MovieRecommendation[] | null>(null);
  const [candidates, setCandidates] = useState<string[]>([]);
  const [currentMovie, setCurrentMovie] = useState<string>('');
  const [pendingMatcherReq, setPendingMatcherReq] = useState<SimilarityRequest | null>(null);
  const [includeSpoilers, setIncludeSpoilers] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  // Auth & User State
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [showProfile, setShowProfile] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem('cine_current_session');
    if (saved) setCurrentUser(JSON.parse(saved));
  }, []);

  const persistUser = (user: User | null) => {
    setCurrentUser(user);
    if (user) {
      localStorage.setItem('cine_current_session', JSON.stringify(user));
      // Update global vault
      const vault = JSON.parse(localStorage.getItem('cine_vault_users') || '[]');
      const idx = vault.findIndex((u: User) => u.username === user.username);
      if (idx !== -1) {
        vault[idx] = user;
        localStorage.setItem('cine_vault_users', JSON.stringify(vault));
      }
    } else {
      localStorage.removeItem('cine_current_session');
    }
  };

  const toggleWatched = (movieTitle: string) => {
    if (!currentUser) return;
    const isWatched = currentUser.watchedMovies.includes(movieTitle);
    const newWatched = isWatched 
      ? currentUser.watchedMovies.filter(m => m !== movieTitle)
      : [...currentUser.watchedMovies, movieTitle];

    persistUser({ ...currentUser, watchedMovies: newWatched });
  };

  const handleSearch = async (query: string, spoilers: boolean) => {
    setLoadingStage(LoadingStage.SEARCHING);
    setAnalysisData(null);
    setCandidates([]);
    setError(null);
    setCurrentMovie(query);
    setIncludeSpoilers(spoilers);

    try {
      const stageTimer = setTimeout(() => setLoadingStage(LoadingStage.ANALYZING), 1000);
      const result = await analyzeMovie(query, spoilers);
      clearTimeout(stageTimer);

      if (result.type === 'SUCCESS') {
        setAnalysisData(result.data);
        setLoadingStage(LoadingStage.COMPLETED);
      } else if (result.type === 'AMBIGUOUS') {
        setCandidates(result.candidates);
        setLoadingStage(LoadingStage.COMPLETED);
      } else if (result.type === 'NOT_FOUND') {
        setError("Movie not found. Try adding the year!");
        setLoadingStage(LoadingStage.ERROR);
      }
    } catch (err) {
      setError("Failed to analyze. Try again later.");
      setLoadingStage(LoadingStage.ERROR);
    }
  };

  const handleMatcherSearch = async (req: SimilarityRequest) => {
    if (!currentUser) return;
    setLoadingStage(LoadingStage.SEARCHING);
    setMatcherResults(null);
    setCandidates([]);
    setError(null);
    setPendingMatcherReq(req);

    try {
      const result = await analyzeMovie(req.sourceMovie, false);
      if (result.type === 'SUCCESS') {
        setLoadingStage(LoadingStage.MATCHING);
        const results = await getSimilarMovies({ ...req, sourceMovie: req.sourceMovie }, currentUser.watchedMovies);
        setMatcherResults(results);
        setLoadingStage(LoadingStage.COMPLETED);
      } else if (result.type === 'AMBIGUOUS') {
        setCandidates(result.candidates);
        setLoadingStage(LoadingStage.COMPLETED);
      } else if (result.type === 'NOT_FOUND') {
        setError("Could not find that specific movie. Try adding the year!");
        setLoadingStage(LoadingStage.ERROR);
      }
    } catch (err) {
      setError("Failed to find similar movies.");
      setLoadingStage(LoadingStage.ERROR);
    }
  };

  const handleCandidateSelect = async (candidate: string) => {
    if (!currentUser) return;
    if (activeTab === 'ANALYZER') {
      handleSearch(candidate, includeSpoilers);
    } else if (activeTab === 'MATCHER' && pendingMatcherReq) {
      setLoadingStage(LoadingStage.MATCHING);
      setCandidates([]);
      try {
        const results = await getSimilarMovies({ ...pendingMatcherReq, sourceMovie: candidate }, currentUser.watchedMovies);
        setMatcherResults(results);
        setLoadingStage(LoadingStage.COMPLETED);
      } catch (err) {
        setError("Failed to find similar movies.");
        setLoadingStage(LoadingStage.ERROR);
      }
    }
  };

  const handleGetRecommendations = async (reqs: RecommendationRequirements) => {
    if (!currentUser) return;
    setLoadingStage(LoadingStage.RECOMMENDING);
    setRecResults(null);
    setError(null);
    try {
      const results = await getRecommendations(reqs, currentUser.watchedMovies);
      setRecResults(results);
      setLoadingStage(LoadingStage.COMPLETED);
    } catch (err) {
      setError("Failed to get recommendations.");
      setLoadingStage(LoadingStage.ERROR);
    }
  };

  const handleReset = () => {
    setAnalysisData(null);
    setRecResults(null);
    setMatcherResults(null);
    setCandidates([]);
    setLoadingStage(LoadingStage.IDLE);
    setCurrentMovie('');
    setPendingMatcherReq(null);
    setError(null);
  };

  const isShowingResults = !!analysisData || !!recResults || !!matcherResults || candidates.length > 0;

  if (!currentUser) {
    return <AuthBooth onLogin={persistUser} />;
  }

  return (
    <div className="min-h-screen bg-cine-black text-white selection:bg-cine-accent flex flex-col font-sans">
      <div className="fixed top-0 left-0 w-full h-full overflow-hidden -z-10 pointer-events-none">
        <div className="absolute -top-[20%] -left-[10%] w-[50%] h-[50%] bg-purple-900/10 rounded-full blur-[120px]"></div>
        <div className="absolute top-[20%] -right-[10%] w-[40%] h-[40%] bg-red-900/10 rounded-full blur-[120px]"></div>
      </div>

      {/* Top Profile Bar */}
      <div className="absolute top-6 right-6 z-50">
        <button 
          onClick={() => setShowProfile(true)}
          className="flex items-center gap-3 bg-cine-dark border border-gray-800 pl-4 pr-2 py-2 rounded-full hover:border-cine-gold transition-all group"
        >
          <span className="text-xs font-bold text-gray-400 group-hover:text-cine-gold uppercase tracking-widest">{currentUser.username}</span>
          <div className="w-8 h-8 rounded-full bg-cine-gold flex items-center justify-center text-cine-black font-black">
            {currentUser.username[0].toUpperCase()}
          </div>
        </button>
      </div>

      {showProfile && <UserProfile user={currentUser} onLogout={() => persistUser(null)} onClose={() => setShowProfile(false)} />}

      {/* Tab Switcher */}
      <div className="container mx-auto px-4 mt-20 md:mt-8">
        <div className="flex justify-center border-b border-gray-800 gap-4 md:gap-8 overflow-x-auto whitespace-nowrap scrollbar-hide">
          <button onClick={() => { setActiveTab('ANALYZER'); handleReset(); }} className={`pb-4 text-[10px] md:text-sm font-bold uppercase tracking-widest transition-all relative ${activeTab === 'ANALYZER' ? 'text-cine-accent' : 'text-gray-500 hover:text-gray-300'}`}>
            Content Moderator {activeTab === 'ANALYZER' && <div className="absolute bottom-0 left-0 w-full h-0.5 bg-cine-accent"></div>}
          </button>
          <button onClick={() => { setActiveTab('RECOMMENDER'); handleReset(); }} className={`pb-4 text-[10px] md:text-sm font-bold uppercase tracking-widest transition-all relative ${activeTab === 'RECOMMENDER' ? 'text-cine-accent' : 'text-gray-500 hover:text-gray-300'}`}>
            Movie Picker {activeTab === 'RECOMMENDER' && <div className="absolute bottom-0 left-0 w-full h-0.5 bg-cine-accent"></div>}
          </button>
          <button onClick={() => { setActiveTab('MATCHER'); handleReset(); }} className={`pb-4 text-[10px] md:text-sm font-bold uppercase tracking-widest transition-all relative ${activeTab === 'MATCHER' ? 'text-cine-accent' : 'text-gray-500 hover:text-gray-300'}`}>
            Movie Matcher {activeTab === 'MATCHER' && <div className="absolute bottom-0 left-0 w-full h-0.5 bg-cine-accent"></div>}
          </button>
        </div>
      </div>

      <main className="flex-grow container mx-auto px-4 sm:px-6 relative z-10 pt-10">
        {activeTab === 'ANALYZER' && (
          <>
            {!isShowingResults && loadingStage === LoadingStage.IDLE && <Hero />}
            <div className={`transition-all duration-500 ${isShowingResults || loadingStage !== LoadingStage.IDLE ? 'mb-8' : 'pb-10'}`}>
               {isShowingResults && (analysisData || candidates.length > 0) ? (
                 <div className="flex justify-between items-center max-w-4xl mx-auto mb-6 bg-cine-gray/20 p-4 rounded-lg backdrop-blur-sm border border-gray-800">
                    <h1 className="text-xl font-bold text-white">Analysis <span className="text-cine-accent">Report</span></h1>
                    <button onClick={handleReset} className="text-xs text-gray-400 hover:text-white underline">New Analysis</button>
                 </div>
               ) : (
                 loadingStage === LoadingStage.IDLE && <SearchBar onSearch={handleSearch} isLoading={loadingStage === LoadingStage.SEARCHING || loadingStage === LoadingStage.ANALYZING} />
               )}
            </div>

            {(loadingStage === LoadingStage.SEARCHING || loadingStage === LoadingStage.ANALYZING) && (
              <div className="flex flex-col items-center justify-center py-20 animate-pulse">
                 <div className="w-16 h-16 border-4 border-cine-gray border-t-cine-accent rounded-full animate-spin mb-6"></div>
                 <p className="text-xl font-medium text-gray-300">Processing...</p>
              </div>
            )}

            {candidates.length > 0 && <DisambiguationOptions candidates={candidates} onSelect={handleCandidateSelect} onCancel={handleReset} />}
            {analysisData && (
              <AnalysisResult 
                data={analysisData} 
                movieTitle={currentMovie} 
                onReset={handleReset} 
                isWatched={currentUser.watchedMovies.includes(currentMovie)}
                onToggleWatched={() => toggleWatched(currentMovie)}
              />
            )}
          </>
        )}

        {activeTab === 'RECOMMENDER' && (
          <RecommendationTab onGetRecommendations={handleGetRecommendations} results={recResults} isLoading={loadingStage === LoadingStage.RECOMMENDING} onReset={handleReset} watchedMovies={currentUser.watchedMovies} onToggleWatched={toggleWatched} />
        )}

        {activeTab === 'MATCHER' && (
          <MovieMatcherTab onSearchSimilar={handleMatcherSearch} results={matcherResults} isLoading={loadingStage === LoadingStage.SEARCHING || loadingStage === LoadingStage.MATCHING} onReset={handleReset} watchedMovies={currentUser.watchedMovies} onToggleWatched={toggleWatched} candidates={candidates} onCandidateSelect={handleCandidateSelect} />
        )}

        {error && (
          <div className="max-w-2xl mx-auto bg-red-900/10 border border-red-500/30 rounded-lg p-6 text-center animate-fade-in my-8">
            <p className="text-red-400">{error}</p>
            <button onClick={handleReset} className="mt-4 text-sm text-gray-400 hover:text-white underline">Back to start</button>
          </div>
        )}
      </main>

      <footer className="py-8 text-center text-gray-600 text-[10px] md:text-xs tracking-widest uppercase">
        © {new Date().getFullYear()} Movie Night Friendly • Built with Gemini
      </footer>
    </div>
  );
};

