}

export interface MovieRecommendation {
  title: string;
  year: string;
  reason: string;
  suitability: string;
}

export type AnalysisResult = 
  | { type: 'SUCCESS'; data: AnalysisData }
  | { type: 'AMBIGUOUS'; candidates: string[] }
  | { type: 'NOT_FOUND' };

export enum LoadingStage {
  IDLE = 'IDLE',
  SEARCHING = 'SEARCHING',
  ANALYZING = 'ANALYZING',
  RECOMMENDING = 'RECOMMENDING',
  MATCHING = 'MATCHING',
  COMPLETED = 'COMPLETED',
  ERROR = 'ERROR'
}

export interface RecommendationRequirements {
  genres: string[];
  company: string;
  pacing: string;
  languages: string[];
  customDescription: string;
}

export interface SimilarityRequest {
  sourceMovie: string;
  reason?: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult, MovieRecommendation, RecommendationRequirements, SimilarityRequest } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const ANALYSIS_SYSTEM_INSTRUCTION = `
You are a film expert and "movie night" curator. Your task is to provide a comprehensive analysis of a movie.

STEP 1: IDENTIFICATION & DISAMBIGUATION
- If the movie DOES NOT EXIST, indicate NOT_FOUND.
- If the title is AMBIGUOUS, provide a list of candidates.

STEP 2: DATA GATHERING
Search for factual data (cast, synopsis, trailer, streaming) and subjective analysis (reception, friendliness).

You must return a JSON object matching the requested schema.
- youtubeTrailerId: Just the ID (e.g., 'dQw4w9WgXcQ') from a high-quality official trailer.
- whereToWatch: A list of major platforms (Netflix, HBO, Disney+, etc.).
- friendliness info: Scrutinize reviews for "group-awkwardness" (nudity, gore, pacing).
`;

export const analyzeMovie = async (movieQuery: string, includeSpoilers: boolean): Promise<AnalysisResult> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analyze: "${movieQuery}". Include Spoilers: ${includeSpoilers}. Search for cast, synopsis, trailer ID, and group-friendliness analysis.`,
      config: {
        systemInstruction: ANALYSIS_SYSTEM_INSTRUCTION,
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            status: { type: Type.STRING, enum: ["SUCCESS", "AMBIGUOUS", "NOT_FOUND"] },
            candidates: { type: Type.ARRAY, items: { type: Type.STRING } },
            general: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                year: { type: Type.STRING },
                synopsis: { type: Type.STRING },
                director: { type: Type.STRING },
                actors: { type: Type.ARRAY, items: { type: Type.STRING } },
                musicScore: { type: Type.STRING },
                youtubeTrailerId: { type: Type.STRING },
                whereToWatch: { type: Type.ARRAY, items: { type: Type.STRING } }
              }
            },
            friendliness: {
              type: Type.OBJECT,
              properties: {
                overallReception: { type: Type.STRING },
                targetAudience: { type: Type.STRING },
                redFlags: { type: Type.STRING },
                contentRisks: { type: Type.STRING },
                prerequisites: { type: Type.STRING }
              }
            }
          }
        }
      },
    });

    const result = JSON.parse(response.text || "{}");

    if (result.status === "NOT_FOUND") return { type: 'NOT_FOUND' };
    if (result.status === "AMBIGUOUS") return { type: 'AMBIGUOUS', candidates: result.candidates || [] };

    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const sources = groundingChunks
      .map((chunk: any) => chunk.web ? { title: chunk.web.title, uri: chunk.web.uri } : null)
      .filter((s: any): s is { title: string; uri: string } => s !== null);

    return {
      type: 'SUCCESS',
      data: {
        general: result.general,
        friendliness: result.friendliness,
        sources
      }
    };
  } catch (error) {
    console.error(error);
    throw error;
  }
};

export const getRecommendations = async (reqs: RecommendationRequirements): Promise<MovieRecommendation[]> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Suggest 5 movies based on: Genres: ${reqs.genres.join(', ')}, Company: ${reqs.company}, Pacing: ${reqs.pacing}, Languages: ${reqs.languages.join(', ')}. Details: ${reqs.customDescription}.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              year: { type: Type.STRING },
              reason: { type: Type.STRING },
              suitability: { type: Type.STRING }
            },
            required: ['title', 'year', 'reason', 'suitability']
          }
        },
        tools: [{ googleSearch: {} }]
      }
    });
    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error(error);
    throw error;
  }
};

export const getSimilarMovies = async (req: SimilarityRequest): Promise<MovieRecommendation[]> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `Suggest 5 movies similar to "${req.sourceMovie}". User context: ${req.reason}.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
