import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult, MovieRecommendation, LanguageGroup, RecommendationRequirements, SimilarityRequest } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const ANALYSIS_SYSTEM_INSTRUCTION = `
You are a world-class film critic and "social viewing" expert. Your task is to provide a surgical analysis of a movie for people planning a "movie night".

STEP 1: IDENTIFICATION & DISAMBIGUATION
- If the movie DOES NOT EXIST, indicate NOT_FOUND.
- If the title is AMBIGUOUS, provide a list of candidates.

STEP 2: DATA GATHERING
Search for factual data (cast, synopsis, trailer, streaming) and deep subjective analysis (reception, social friendliness).

STEP 3: SOCIAL ANALYSIS
You must evaluate the movie's "Group Friendliness".
- friendlinessScore: (0-100) How universally "safe" and enjoyable is this for a random group?
- sensitivity scores (0-10): 0 is none/clean, 10 is extreme. 
  - nuditySex: Includes awkward scenes.
  - violenceGore: Physical horror or intensity.
  - profanity: Language frequency.
  - awkwardnessFactor: Specifically "cringe" moments when watching with others (parents, dates).
- groupSuitability: One-sentence verdict for specific group contexts.

You must return a JSON object matching the requested schema.
`;

export const analyzeMovie = async (movieQuery: string, includeSpoilers: boolean): Promise<AnalysisResult> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analyze: "${movieQuery}". Spoilers: ${includeSpoilers}. Detailed social friendliness report required.`,
      config: {
        systemInstruction: ANALYSIS_SYSTEM_INSTRUCTION,
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            status: { type: Type.STRING, enum: ["SUCCESS", "AMBIGUOUS", "NOT_FOUND"] },
            candidates: { type: Type.ARRAY, items: { type: Type.STRING } },
            general: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                year: { type: Type.STRING },
                synopsis: { type: Type.STRING },
                director: { type: Type.STRING },
                actors: { type: Type.ARRAY, items: { type: Type.STRING } },
                musicScore: { type: Type.STRING },
                youtubeTrailerId: { type: Type.STRING },
                whereToWatch: { type: Type.ARRAY, items: { type: Type.STRING } }
              }
            },
            friendliness: {
              type: Type.OBJECT,
              properties: {
                friendlinessScore: { type: Type.NUMBER },
                overallReception: { type: Type.STRING },
                targetAudience: { type: Type.STRING },
                suitability: {
                  type: Type.OBJECT,
                  properties: {
                    familyWithKids: { type: Type.STRING },
                    firstDate: { type: Type.STRING },
                    cinephiles: { type: Type.STRING },
                    casualFriends: { type: Type.STRING }
                  }
                },
                sensitivity: {
                  type: Type.OBJECT,
                  properties: {
                    nuditySex: { type: Type.NUMBER },
                    violenceGore: { type: Type.NUMBER },
                    profanity: { type: Type.NUMBER },
                    awkwardnessFactor: { type: Type.NUMBER }
                  }
                },
                redFlags: { type: Type.STRING },
                contentRisks: { type: Type.STRING },
                prerequisites: { type: Type.STRING },
                proTips: { type: Type.STRING }
              }
            }
          }
        }
      },
    });

    const result = JSON.parse(response.text || "{}");

    if (result.status === "NOT_FOUND") return { type: 'NOT_FOUND' };
    if (result.status === "AMBIGUOUS") return { type: 'AMBIGUOUS', candidates: result.candidates || [] };

    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const sources = groundingChunks
      .map((chunk: any) => chunk.web ? { title: chunk.web.title, uri: chunk.web.uri } : null)
      .filter((s: any): s is { title: string; uri: string } => s !== null);

    return {
      type: 'SUCCESS',
      data: {
        general: result.general,
        friendliness: result.friendliness,
        sources
      }
    };
  } catch (error) {
    console.error(error);
    throw error;
  }
};

export const getRecommendations = async (reqs: RecommendationRequirements): Promise<LanguageGroup[]> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
