          <p className="text-sm"><strong>Audience:</strong> {formData.company}</p>
          <p className="text-sm"><strong>Pacing:</strong> {formData.pacing}</p>
        </div>

        {results.map((group, groupIdx) => (
          <div key={groupIdx} className="mb-12 animate-fade-in section-break" style={{ animationDelay: `${groupIdx * 0.1}s` }}>
            <div className="flex items-center gap-4 mb-6">
