                    </div>
                    <span className={`text-sm ${formData.languages.includes(lang) ? 'text-white' : 'text-gray-400'}`}>{lang}</span>
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>

        <div className="mb-8">
          <label className="block text-gray-400 text-sm font-bold mb-3 uppercase tracking-wider">How fast should it move?</label>
          <div className="grid grid-cols-3 gap-3">
            {PACING.map(p => (
              <button key={p} type="button" onClick={() => setFormData(prev => ({...prev, pacing: p}))} className={`py-3 rounded-lg text-[10px] font-bold border transition-all ${formData.pacing === p ? 'border-cine-gold text-cine-gold bg-cine-gold/5' : 'border-gray-800 text-gray-500 hover:border-gray-600'}`}>{p}</button>
            ))}
          </div>
        </div>

        <textarea className="w-full bg-cine-black border border-gray-700 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-cine-accent h-24 mb-8" placeholder="Anything else? (Optional)" value={formData.customDescription} onChange={(e) => setFormData(p => ({...p, customDescription: e.target.value}))} />

        <button type="submit" disabled={isLoading || formData.genres.length === 0} className="w-full bg-gradient-to-r from-cine-accent to-red-600 py-4 rounded-xl font-bold text-white shadow-xl disabled:opacity-50">
          {isLoading ? 'Curating Your List...' : 'Get Top Recommendations'}
        </button>
      </form>
    </div>
  );
};

import React, { useState } from 'react';
import { MovieRecommendation, SimilarityRequest } from '../types';
import { DisambiguationOptions } from './DisambiguationOptions';

interface MovieMatcherTabProps {
  onSearchSimilar: (req: SimilarityRequest) => void;
  results: MovieRecommendation[] | null;
  isLoading: boolean;
  onReset: () => void;
  candidates: string[];
  onCandidateSelect: (candidate: string) => void;
}

export const MovieMatcherTab: React.FC<MovieMatcherTabProps> = ({ onSearchSimilar, results, isLoading, onReset, candidates, onCandidateSelect }) => {
  const [query, setQuery] = useState('');
  const [reason, setReason] = useState('');

  const handleDownloadReport = () => {
    const originalTitle = document.title;
    document.title = `CineMatcher_SimilarTo_${query.replace(/\s+/g, '_')}`;
    setTimeout(() => {
      window.print();
      document.title = originalTitle;
    }, 250);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (query.trim() && !isLoading) {
      onSearchSimilar({ sourceMovie: query, reason });
    }
  };

  if (candidates.length > 0) {
    return <DisambiguationOptions candidates={candidates} onSelect={onCandidateSelect} onCancel={onReset} />;
  }

  if (results) {
    return (
      <div className="max-w-4xl mx-auto w-full pb-20 animate-fade-in">
        <div className="flex justify-between items-center mb-8 border-b border-gray-800 pb-4">
          <h2 className="text-2xl font-bold text-white">Your "Cine-Matches" 🎬</h2>
          <div className="flex items-center gap-4 no-print">
            <button 
              type="button"
              onClick={handleDownloadReport}
              className="flex items-center gap-2 bg-cine-gold text-cine-black text-[10px] font-black uppercase tracking-widest px-4 py-2 rounded-lg hover:bg-cine-gold/90 transition-all shadow-lg active:scale-95"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
              Download PDF
            </button>
            <button onClick={onReset} className="text-sm text-gray-400 hover:text-white underline">Find Another</button>
          </div>
        </div>

        <div className="print-only mb-8 text-black">
          <h1 className="text-2xl font-black border-b pb-2 mb-4 uppercase">Cine-Matcher Report</h1>
          <p className="text-sm"><strong>Original Film Context:</strong> {query}</p>
          {reason && <p className="text-sm"><strong>Specific Preferences:</strong> {reason}</p>}
          <p className="text-sm text-gray-500 mt-2 italic">Generated: {new Date().toLocaleDateString()}</p>
        </div>

        <div className="grid gap-6">
          {results.map((movie, idx) => (
            <div key={idx} className="bg-cine-gray/30 border border-gray-800 rounded-xl p-6 hover:border-cine-accent transition-all duration-300">
              <div className="flex justify-between items-start mb-3">
                <h3 className="text-xl font-bold text-white">{movie.title} <span className="text-gray-500 text-base">({movie.year})</span></h3>
                <span className="bg-cine-gold/20 text-cine-gold text-[10px] uppercase font-bold px-2 py-1 rounded no-print">Match High</span>
              </div>
              <p className="text-gray-300 mb-4 leading-relaxed"><strong className="text-cine-accent uppercase text-xs tracking-wider block mb-1">Why you'll love it:</strong> {movie.reason}</p>
              <div className="bg-cine-black/50 rounded-lg p-3 border border-gray-800/50 text-sm text-gray-400 italic">
                 <span className="text-gray-500 font-bold not-italic mr-2">VIBE CHECK:</span>
                 {movie.suitability}
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto w-full animate-fade-in pb-20 no-print">
      <form onSubmit={handleSubmit} className="bg-cine-dark border border-gray-800 rounded-2xl p-8 shadow-2xl">
        <h2 className="text-2xl font-bold text-white mb-2 text-center">Find your ideal movies</h2>
        <p className="text-gray-400 text-center mb-8">Enter a movie you loved, and we'll find others with the same type and mood.</p>

        <input type="text" className="w-full bg-cine-black border border-gray-700 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-cine-accent mb-6" placeholder="The Movie You Loved (e.g. Inception)" value={query} onChange={(e) => setQuery(e.target.value)} disabled={isLoading} />
        <textarea className="w-full bg-cine-black border border-gray-700 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-cine-accent h-32 resize-none mb-8" placeholder="What specifically did you enjoy? (Optional)" value={reason} onChange={(e) => setReason(e.target.value)} disabled={isLoading} />

        <button type="submit" disabled={isLoading || !query.trim()} className="w-full bg-gradient-to-r from-cine-gold to-yellow-600 py-4 rounded-xl font-bold text-black shadow-xl disabled:opacity-50">
          {isLoading ? 'Scanning the Cinema Multiverse...' : 'Find Matches'}
        </button>
      </form>
    </div>
  );
};

