              <h3 style={{ fontSize: '12pt' }}>Group Contexts</h3>
              <p><strong>Family Night:</strong> {friendliness.suitability.familyWithKids}</p>
              <p><strong>First Date:</strong> {friendliness.suitability.firstDate}</p>
              <p><strong>Casual Friends:</strong> {friendliness.suitability.casualFriends}</p>
              <p><strong>The Cinephile Club:</strong> {friendliness.suitability.cinephiles}</p>
            </div>

            <div style={{ marginTop: '30px', padding: '15px', border: '1px dashed #d40000', backgroundColor: '#fff5f5' }}>
              <h3 style={{ fontSize: '12pt', color: '#d40000' }}>Expert Pro Tip</h3>
              <p style={{ fontSize: '11pt', fontWeight: 'bold' }}>{friendliness.proTips}</p>
            </div>
          </div>
        </div>
      </div>

      {sources.length > 0 && (
        <div className="mt-12 border-t border-gray-800 pt-6 no-print">
          <h4 className="text-[10px] font-bold text-gray-500 uppercase tracking-[0.3em] mb-4 text-center">Data Grounding Points</h4>
          <div className="flex flex-wrap justify-center gap-2">
            {sources.map((source, idx) => (
              <a 
                key={idx}
                href={source.uri}
                target="_blank"
                rel="noopener noreferrer"
                className="text-[10px] bg-cine-gray hover:bg-gray-700 text-gray-300 px-3 py-1.5 rounded transition-all uppercase font-bold tracking-wider"
              >
                {source.title || new URL(source.uri).hostname}
              </a>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { RecommendationRequirements, LanguageGroup } from '../types';

interface RecommendationTabProps {
  onGetRecommendations: (reqs: RecommendationRequirements) => void;
  results: LanguageGroup[] | null;
  isLoading: boolean;
  onReset: () => void;
}

const GENRES = ["Action", "Comedy", "Horror", "Thriller", "Sci-Fi", "Drama", "Romance", "Documentary", "Animated", "Mystery"];
const COMPANIES = ["Solo", "Family", "Friends", "Cinephiles/Critics"];
const PACING = ["Fast & Furious", "Balanced", "Slow Burn"];
const LANGUAGES = ["Any Language", "English", "French", "German", "Hindi", "Italian", "Japanese", "Kannada", "Korean", "Malayalam", "Mandarin", "Portuguese", "Spanish", "Tamil", "Telugu"].sort((a, b) => a === "Any Language" ? -1 : b === "Any Language" ? 1 : a.localeCompare(b));

export const RecommendationTab: React.FC<RecommendationTabProps> = ({ onGetRecommendations, results, isLoading, onReset }) => {
  const [formData, setFormData] = useState<RecommendationRequirements>({
    genres: [],
    company: 'Solo',
    pacing: 'Balanced',
    languages: ['Any Language'],
    customDescription: ''
  });

  const [isExporting, setIsExporting] = useState(false);
  const [isLangDropdownOpen, setIsLangDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const pdfRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsLangDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleDownloadReport = async () => {
    if (!pdfRef.current || isExporting) return;

    setIsExporting(true);
    const element = pdfRef.current;
    const opt = {
      margin: 10,
      filename: `MoviePicker_Recommendations_${new Date().toLocaleDateString().replace(/\//g, '-')}.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 2 },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
    };

    try {
      // @ts-ignore
      await html2pdf().set(opt).from(element).save();
    } catch (err) {
      console.error("PDF Export failed:", err);
    } finally {
      setIsExporting(false);
    }
  };

  const toggleGenre = (genre: string) => {
    setFormData(prev => ({
      ...prev,
      genres: prev.genres.includes(genre) ? prev.genres.filter(g => g !== genre) : [...prev.genres, genre]
    }));
  };

  const toggleLanguage = (lang: string) => {
    setFormData(prev => {
      let newLangs = [...prev.languages];
      if (lang === "Any Language") return { ...prev, languages: ["Any Language"] };
      if (newLangs.includes(lang)) {
        newLangs = newLangs.filter(l => l !== lang);
        if (newLangs.length === 0) newLangs = ["Any Language"];
      } else {
        newLangs = newLangs.filter(l => l !== "Any Language");
        newLangs.push(lang);
      }
      return { ...prev, languages: newLangs };
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onGetRecommendations(formData);
  };

  if (results) {
    return (
      <div className="max-w-4xl mx-auto w-full pb-20 animate-fade-in">
        <div className="flex justify-between items-center mb-10 border-b border-gray-800 pb-4 no-print">
          <h2 className="text-2xl font-bold text-white">Your Curated Picks 🍿</h2>
          <div className="flex items-center gap-4">
            <button 
              type="button"
              disabled={isExporting}
              onClick={handleDownloadReport}
              className={`flex items-center gap-2 bg-cine-gold text-cine-black text-[10px] font-black uppercase tracking-widest px-4 py-2 rounded-lg transition-all shadow-lg active:scale-95 ${isExporting ? 'opacity-50' : 'hover:bg-cine-gold/90'}`}
            >
              <svg className={`w-4 h-4 ${isExporting ? 'animate-spin' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
              </svg>
              {isExporting ? 'Generating...' : 'Download PDF'}
            </button>
            <button onClick={onReset} className="text-sm text-gray-400 hover:text-white underline">Start Over</button>
          </div>
        </div>

        {results.map((group, groupIdx) => (
          <div key={groupIdx} className="mb-12 animate-fade-in" style={{ animationDelay: `${groupIdx * 0.1}s` }}>
            <div className="flex items-center gap-4 mb-6 no-print">
              <div className="h-px flex-grow bg-gradient-to-r from-transparent to-gray-800"></div>
              <h3 className="text-xs font-black text-cine-gold uppercase tracking-[0.3em] whitespace-nowrap">
                {group.language} Selection
              </h3>
              <div className="h-px flex-grow bg-gradient-to-l from-transparent to-gray-800"></div>
            </div>

            <div className="grid gap-6">
              {group.movies.map((movie, idx) => (
                <div key={idx} className="bg-cine-gray/30 border border-gray-800 rounded-xl p-6 hover:border-cine-accent transition-all duration-300">
                  <div className="flex justify-between items-start mb-3">
                    <h3 className="text-xl font-bold text-white">{movie.title} <span className="text-gray-500 text-base">({movie.year})</span></h3>
                  </div>
                  <p className="text-gray-300 mb-4 leading-relaxed"><strong className="text-cine-gold uppercase text-xs tracking-wider block mb-1">Why it matches:</strong> {movie.reason}</p>
                  <div className="bg-cine-black/50 rounded-lg p-3 border border-gray-800/50 text-sm text-gray-400 italic">
                    <span className="text-gray-500 font-bold not-italic mr-2">VIBE CHECK:</span>
                    {movie.suitability}
                  </div>
                </div>
              ))}
            </div>
          </div>
        ))}

        {/* HIDDEN TEMPLATE FOR PDF */}
        <div style={{ position: 'absolute', left: '-9999px', top: '-9999px' }}>
          <div ref={pdfRef} className="pdf-template">
            <h1>Cine-Vault Picks</h1>
            <p style={{ color: '#666' }}>Recommendations based on: {formData.genres.join(', ')} • {formData.company}</p>

            {results.map((group, gIdx) => (
              <div key={gIdx} style={{ marginTop: '30px' }}>
                <h2 style={{ fontSize: '14pt', borderBottom: '1px solid #ccc' }}>{group.language} Selection</h2>
                {group.movies.map((m, mIdx) => (
                  <div key={mIdx} style={{ marginBottom: '20px', paddingBottom: '15px', borderBottom: '1px dotted #eee' }}>
                    <p style={{ fontSize: '12pt', fontWeight: 'bold' }}>{mIdx + 1}. {m.title} ({m.year})</p>
                    <p style={{ fontSize: '10pt', color: '#444' }}><strong>Reason:</strong> {m.reason}</p>
                    <p style={{ fontSize: '9pt', color: '#777', fontStyle: 'italic' }}>Match Vibe: {m.suitability}</p>
                  </div>
                ))}
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto w-full animate-fade-in pb-20">
      <form onSubmit={handleSubmit} className="bg-cine-dark border border-gray-800 rounded-2xl p-8 shadow-2xl">
        <h2 className="text-2xl font-bold text-white mb-6 text-center">Describe Your Perfect Movie</h2>

        <div className="mb-8">
          <label className="block text-gray-400 text-sm font-bold mb-3 uppercase tracking-wider">Which vibes are we feeling?</label>
          <div className="flex flex-wrap gap-2">
            {GENRES.map(genre => (
              <button key={genre} type="button" onClick={() => toggleGenre(genre)} className={`px-3 py-1.5 rounded-full text-xs font-medium transition-all ${formData.genres.includes(genre) ? 'bg-cine-accent text-white shadow-lg' : 'bg-gray-800 text-gray-400 hover:bg-gray-700'}`}>
                {genre}
              </button>
            ))}
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
          <div>
            <label className="block text-gray-400 text-sm font-bold mb-3 uppercase tracking-wider">Who's on the couch?</label>
            <select value={formData.company} onChange={(e) => setFormData(p => ({...p, company: e.target.value}))} className="w-full bg-cine-black border border-gray-700 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-cine-accent">
              {COMPANIES.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>

          <div className="relative" ref={dropdownRef}>
            <label className="block text-gray-400 text-sm font-bold mb-3 uppercase tracking-wider">Language Preference</label>
            <button type="button" onClick={() => setIsLangDropdownOpen(!isLangDropdownOpen)} className="w-full bg-cine-black border border-gray-700 rounded-lg px-4 py-3 text-white text-left flex justify-between items-center focus:border-cine-accent">
              <span className="truncate pr-2">{formData.languages.join(', ')}</span>
              <svg className={`w-4 h-4 transition-transform ${isLangDropdownOpen ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
            </button>
            {isLangDropdownOpen && (
              <div className="absolute z-50 w-full mt-2 bg-cine-gray border border-gray-700 rounded-lg shadow-2xl max-h-60 overflow-y-auto">
                {LANGUAGES.map(lang => (
                  <button key={lang} type="button" onClick={() => toggleLanguage(lang)} className="w-full flex items-center px-4 py-3 hover:bg-cine-accent/10 text-left border-b border-gray-800 last:border-0">
                    <div className={`w-4 h-4 rounded border mr-3 flex items-center justify-center ${formData.languages.includes(lang) ? 'bg-cine-accent border-cine-accent' : 'border-gray-500'}`}>
                      {formData.languages.includes(lang) && <svg className="w-3 h-3 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>}
                    </div>
                    <span className={`text-sm ${formData.languages.includes(lang) ? 'text-white' : 'text-gray-400'}`}>{lang}</span>
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>

        <div className="mb-8">
          <label className="block text-gray-400 text-sm font-bold mb-3 uppercase tracking-wider">How fast should it move?</label>
          <div className="grid grid-cols-3 gap-3">
            {PACING.map(p => (
              <button key={p} type="button" onClick={() => setFormData(prev => ({...prev, pacing: p}))} className={`py-3 rounded-lg text-[10px] font-bold border transition-all ${formData.pacing === p ? 'border-cine-gold text-cine-gold bg-cine-gold/5' : 'border-gray-800 text-gray-500 hover:border-gray-600'}`}>{p}</button>
            ))}
          </div>
        </div>

        <textarea className="w-full bg-cine-black border border-gray-700 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-cine-accent h-24 mb-8" placeholder="Anything else? (Optional)" value={formData.customDescription} onChange={(e) => setFormData(p => ({...p, customDescription: e.target.value}))} />

        <button type="submit" disabled={isLoading || formData.genres.length === 0} className="w-full bg-gradient-to-r from-cine-accent to-red-600 py-4 rounded-xl font-bold text-white shadow-xl disabled:opacity-50">
          {isLoading ? 'Curating Your List...' : 'Get Top Recommendations'}
        </button>
      </form>
    </div>
  );
};

import React, { useState } from 'react';
import { Hero } from './components/Hero';
import { SearchBar } from './components/SearchBar';
import { AnalysisResult } from './components/AnalysisResult';
import { DisambiguationOptions } from './components/DisambiguationOptions';
import { RecommendationTab } from './components/RecommendationTab';
import { MovieMatcherTab } from './components/MovieMatcherTab';
import { analyzeMovie, getRecommendations, getSimilarMovies } from './services/geminiService';
import { AnalysisData, LoadingStage, MovieRecommendation, LanguageGroup, RecommendationRequirements, SimilarityRequest } from './types';

type Tab = 'ANALYZER' | 'RECOMMENDER' | 'MATCHER';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>('ANALYZER');
  const [loadingStage, setLoadingStage] = useState<LoadingStage>(LoadingStage.IDLE);
  const [analysisData, setAnalysisData] = useState<AnalysisData | null>(null);
  const [recResults, setRecResults] = useState<LanguageGroup[] | null>(null);
  const [matcherResults, setMatcherResults] = useState<MovieRecommendation[] | null>(null);
  const [candidates, setCandidates] = useState<string[]>([]);
  const [currentMovie, setCurrentMovie] = useState<string>('');
  const [pendingMatcherReq, setPendingMatcherReq] = useState<SimilarityRequest | null>(null);
  const [includeSpoilers, setIncludeSpoilers] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  const handleSearch = async (query: string, spoilers: boolean) => {
    setLoadingStage(LoadingStage.SEARCHING);
    setAnalysisData(null);
    setCandidates([]);
    setError(null);
    setCurrentMovie(query);
    setIncludeSpoilers(spoilers);

    try {
      const stageTimer = setTimeout(() => setLoadingStage(LoadingStage.ANALYZING), 1000);
      const result = await analyzeMovie(query, spoilers);
      clearTimeout(stageTimer);

      if (result.type === 'SUCCESS') {
        setAnalysisData(result.data);
        setLoadingStage(LoadingStage.COMPLETED);
      } else if (result.type === 'AMBIGUOUS') {
        setCandidates(result.candidates);
        setLoadingStage(LoadingStage.COMPLETED);
      } else if (result.type === 'NOT_FOUND') {
        setError("Movie not found. Try adding the year!");
        setLoadingStage(LoadingStage.ERROR);
      }
    } catch (err) {
      setError("Failed to analyze. Try again later.");
      setLoadingStage(LoadingStage.ERROR);
    }
  };

  const handleMatcherSearch = async (req: SimilarityRequest) => {
    setLoadingStage(LoadingStage.SEARCHING);
    setMatcherResults(null);
    setCandidates([]);
    setError(null);
    setPendingMatcherReq(req);

    try {
      const result = await analyzeMovie(req.sourceMovie, false);
      if (result.type === 'SUCCESS') {
        setLoadingStage(LoadingStage.MATCHING);
        const results = await getSimilarMovies({ ...req, sourceMovie: req.sourceMovie });
        setMatcherResults(results);
        setLoadingStage(LoadingStage.COMPLETED);
      } else if (result.type === 'AMBIGUOUS') {
        setCandidates(result.candidates);
        setLoadingStage(LoadingStage.COMPLETED);
      } else if (result.type === 'NOT_FOUND') {
        setError("Could not find that specific movie. Try adding the year!");
        setLoadingStage(LoadingStage.ERROR);
      }
    } catch (err) {
      setError("Failed to find similar movies.");
      setLoadingStage(LoadingStage.ERROR);
    }
  };

  const handleCandidateSelect = async (candidate: string) => {
    if (activeTab === 'ANALYZER') {
      handleSearch(candidate, includeSpoilers);
    } else if (activeTab === 'MATCHER' && pendingMatcherReq) {
      setLoadingStage(LoadingStage.MATCHING);
      setCandidates([]);
      try {
        const results = await getSimilarMovies({ ...pendingMatcherReq, sourceMovie: candidate });
        setMatcherResults(results);
        setLoadingStage(LoadingStage.COMPLETED);
      } catch (err) {
        setError("Failed to find similar movies.");
        setLoadingStage(LoadingStage.ERROR);
      }
    }
  };

  const handleGetRecommendations = async (reqs: RecommendationRequirements) => {
    setLoadingStage(LoadingStage.RECOMMENDING);
    setRecResults(null);
    setError(null);
    try {
      const results = await getRecommendations(reqs);
      setRecResults(results);
      setLoadingStage(LoadingStage.COMPLETED);
    } catch (err) {
      setError("Failed to get recommendations.");
      setLoadingStage(LoadingStage.ERROR);
    }
  };

  const handleReset = () => {
    setAnalysisData(null);
    setRecResults(null);
    setMatcherResults(null);
    setCandidates([]);
    setLoadingStage(LoadingStage.IDLE);
    setCurrentMovie('');
    setPendingMatcherReq(null);
    setError(null);
  };

  const isShowingResults = !!analysisData || !!recResults || !!matcherResults || candidates.length > 0;

  return (
    <div className="min-h-screen bg-cine-black text-white selection:bg-cine-accent flex flex-col font-sans">
      <div className="fixed top-0 left-0 w-full h-full overflow-hidden -z-10 pointer-events-none">
        <div className="absolute -top-[20%] -left-[10%] w-[50%] h-[50%] bg-purple-900/10 rounded-full blur-[120px]"></div>
        <div className="absolute top-[20%] -right-[10%] w-[40%] h-[40%] bg-red-900/10 rounded-full blur-[120px]"></div>
      </div>

      {/* Tab Switcher */}
      <div className="container mx-auto px-4 mt-8">
        <div className="flex justify-center border-b border-gray-800 gap-4 md:gap-8 overflow-x-auto whitespace-nowrap scrollbar-hide">
          <button onClick={() => { setActiveTab('ANALYZER'); handleReset(); }} className={`pb-4 text-[10px] md:text-sm font-bold uppercase tracking-widest transition-all relative ${activeTab === 'ANALYZER' ? 'text-cine-accent' : 'text-gray-500 hover:text-gray-300'}`}>
            Content Moderator {activeTab === 'ANALYZER' && <div className="absolute bottom-0 left-0 w-full h-0.5 bg-cine-accent"></div>}
          </button>
          <button onClick={() => { setActiveTab('RECOMMENDER'); handleReset(); }} className={`pb-4 text-[10px] md:text-sm font-bold uppercase tracking-widest transition-all relative ${activeTab === 'RECOMMENDER' ? 'text-cine-accent' : 'text-gray-500 hover:text-gray-300'}`}>
            Movie Picker {activeTab === 'RECOMMENDER' && <div className="absolute bottom-0 left-0 w-full h-0.5 bg-cine-accent"></div>}
          </button>
          <button onClick={() => { setActiveTab('MATCHER'); handleReset(); }} className={`pb-4 text-[10px] md:text-sm font-bold uppercase tracking-widest transition-all relative ${activeTab === 'MATCHER' ? 'text-cine-accent' : 'text-gray-500 hover:text-gray-300'}`}>
            Movie Matcher {activeTab === 'MATCHER' && <div className="absolute bottom-0 left-0 w-full h-0.5 bg-cine-accent"></div>}
          </button>
        </div>
      </div>

      <main className="flex-grow container mx-auto px-4 sm:px-6 relative z-10 pt-10">
        {activeTab === 'ANALYZER' && (
          <>
            {!isShowingResults && loadingStage === LoadingStage.IDLE && <Hero />}
            <div className={`transition-all duration-500 ${isShowingResults || loadingStage !== LoadingStage.IDLE ? 'mb-8' : 'pb-10'}`}>
               {isShowingResults && (analysisData || candidates.length > 0) ? (
                 <div className="flex justify-between items-center max-w-4xl mx-auto mb-6 bg-cine-gray/20 p-4 rounded-lg backdrop-blur-sm border border-gray-800">
                    <h1 className="text-xl font-bold text-white">Full <span className="text-cine-accent">Movie Dossier</span></h1>
                    <button onClick={handleReset} className="text-xs text-gray-400 hover:text-white underline">New Search</button>
                 </div>
               ) : (
                 /* Fix narrowing error: when loadingStage is checked to be IDLE, subsequent checks for SEARCHING or ANALYZING within the same scope are unreachable and cause TypeScript errors. Since the SearchBar is only rendered when IDLE in this context, isLoading is set to false. */
                 loadingStage === LoadingStage.IDLE && <SearchBar onSearch={handleSearch} isLoading={false} />
               )}
            </div>

            {(loadingStage === LoadingStage.SEARCHING || loadingStage === LoadingStage.ANALYZING) && (
              <div className="flex flex-col items-center justify-center py-20 animate-pulse">
                 <div className="w-16 h-16 border-4 border-cine-gray border-t-cine-accent rounded-full animate-spin mb-6"></div>
                 <p className="text-xl font-medium text-gray-300">Curating Data...</p>
              </div>
            )}

            {candidates.length > 0 && <DisambiguationOptions candidates={candidates} onSelect={handleCandidateSelect} onCancel={handleReset} />}
            {analysisData && (
              <AnalysisResult 
                data={analysisData} 
                onReset={handleReset} 
              />
            )}
          </>
        )}

        {activeTab === 'RECOMMENDER' && (
          <RecommendationTab onGetRecommendations={handleGetRecommendations} results={recResults} isLoading={loadingStage === LoadingStage.RECOMMENDING} onReset={handleReset} />
        )}

        {activeTab === 'MATCHER' && (
          <MovieMatcherTab onSearchSimilar={handleMatcherSearch} results={matcherResults} isLoading={loadingStage === LoadingStage.SEARCHING || loadingStage === LoadingStage.MATCHING} onReset={handleReset} candidates={candidates} onCandidateSelect={handleCandidateSelect} />
        )}

        {error && (
          <div className="max-w-2xl mx-auto bg-red-900/10 border border-red-500/30 rounded-lg p-6 text-center animate-fade-in my-8">
            <p className="text-red-400">{error}</p>
            <button onClick={handleReset} className="mt-4 text-sm text-gray-400 hover:text-white underline">Back to start</button>
          </div>
        )}
      </main>

      <footer className="py-8 text-center text-gray-600 text-[10px] md:text-xs tracking-widest uppercase">
        © {new Date().getFullYear()} Movie Night Friendly • Built with Gemini
      </footer>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult, MovieRecommendation, LanguageGroup, RecommendationRequirements, SimilarityRequest } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const ANALYSIS_SYSTEM_INSTRUCTION = `
You are a world-class film critic and "social viewing" expert. Your task is to provide a surgical analysis of a movie for people planning a "movie night".

STEP 1: IDENTIFICATION & DISAMBIGUATION
- If the movie DOES NOT EXIST, indicate NOT_FOUND.
- If the title is AMBIGUOUS, provide a list of candidates.

STEP 2: DATA GATHERING
Search for factual data (cast, synopsis, trailer, streaming) and deep subjective analysis (reception, social friendliness).

STEP 3: SOCIAL ANALYSIS
You must evaluate the movie's "Group Friendliness".
- friendlinessScore: (0-100) How universally "safe" and enjoyable is this for a random group?
- sensitivity scores (0-10): 0 is none/clean, 10 is extreme. 
  - nuditySex: Includes awkward scenes.
  - violenceGore: Physical horror or intensity.
  - profanity: Language frequency.
  - awkwardnessFactor: Specifically "cringe" moments when watching with others (parents, dates).
- groupSuitability: One-sentence verdict for specific group contexts.

You must return a JSON object matching the requested schema. Ensure all fields in 'general' and 'friendliness' are populated.
`;

export const analyzeMovie = async (movieQuery: string, includeSpoilers: boolean): Promise<AnalysisResult> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analyze: "${movieQuery}". Spoilers: ${includeSpoilers}. Detailed social friendliness report required.`,
      config: {
        systemInstruction: ANALYSIS_SYSTEM_INSTRUCTION,
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            status: { type: Type.STRING, enum: ["SUCCESS", "AMBIGUOUS", "NOT_FOUND"] },
            candidates: { type: Type.ARRAY, items: { type: Type.STRING } },
            general: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                year: { type: Type.STRING },
                synopsis: { type: Type.STRING },
                director: { type: Type.STRING },
                actors: { type: Type.ARRAY, items: { type: Type.STRING } },
                musicScore: { type: Type.STRING },
                youtubeTrailerId: { type: Type.STRING },
                whereToWatch: { type: Type.ARRAY, items: { type: Type.STRING } }
              }
            },
            friendliness: {
              type: Type.OBJECT,
              properties: {
                friendlinessScore: { type: Type.NUMBER },
                overallReception: { type: Type.STRING },
                targetAudience: { type: Type.STRING },
                suitability: {
                  type: Type.OBJECT,
                  properties: {
                    familyWithKids: { type: Type.STRING },
                    firstDate: { type: Type.STRING },
                    cinephiles: { type: Type.STRING },
                    casualFriends: { type: Type.STRING }
                  }
                },
                sensitivity: {
                  type: Type.OBJECT,
                  properties: {
                    nuditySex: { type: Type.NUMBER },
                    violenceGore: { type: Type.NUMBER },
                    profanity: { type: Type.NUMBER },
                    awkwardnessFactor: { type: Type.NUMBER }
                  }
                },
                redFlags: { type: Type.STRING },
                contentRisks: { type: Type.STRING },
                prerequisites: { type: Type.STRING },
                proTips: { type: Type.STRING }
              }
            }
          }
        }
      },
    });

    const result = JSON.parse(response.text || "{}");

    if (result.status === "NOT_FOUND") return { type: 'NOT_FOUND' };
    if (result.status === "AMBIGUOUS") return { type: 'AMBIGUOUS', candidates: result.candidates || [] };

    // Robust fallbacks for missing data
    const general = result.general || {
      title: movieQuery,
      year: "Unknown",
      synopsis: "No data available.",
      director: "Unknown",
      actors: [],
      musicScore: "N/A",
      youtubeTrailerId: "",
      whereToWatch: []
    };

    const friendliness = result.friendliness || {
      friendlinessScore: 0,
      overallReception: "No analysis available.",
      targetAudience: "N/A",
      suitability: { familyWithKids: "N/A", firstDate: "N/A", cinephiles: "N/A", casualFriends: "N/A" },
      sensitivity: { nuditySex: 0, violenceGore: 0, profanity: 0, awkwardnessFactor: 0 },
      redFlags: "N/A",
      contentRisks: "N/A",
      prerequisites: "N/A",
      proTips: "N/A"
    };

    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const sources = groundingChunks
      .map((chunk: any) => chunk.web ? { title: chunk.web.title, uri: chunk.web.uri } : null)
      .filter((s: any): s is { title: string; uri: string } => s !== null);

    return {
      type: 'SUCCESS',
      data: {
        general,
        friendliness,
        sources
      }
    };
  } catch (error) {
    console.error(error);
    throw error;
  }
};

