};

export interface GroundingChunk {
  web?: {
    uri: string;
    title: string;
  };
}

export interface GeneralInfo {
  title: string;
  year: string;
  synopsis: string;
  director: string;
  actors: string[];
  musicScore: string;
  youtubeTrailerId: string;
  whereToWatch: string[];
}

export interface GroupSuitability {
  familyWithKids: string;
  firstDate: string;
  cinephiles: string;
  casualFriends: string;
}

export interface ContentSensitivity {
  nuditySex: number; // 0-10
  violenceGore: number; // 0-10
  profanity: number; // 0-10
  awkwardnessFactor: number; // 0-10
  pacingDrag: number; // 0-10 (how slow/draggy)
  complexity: number; // 0-10 (how confusing/lore-heavy)
  brainrot: number; // 0-10 (nonsense/low-quality content)
}

export interface FriendlinessInfo {
  friendlinessScore: number;
  overallReception: string;
  idealFor: string; // Elements that make it suited to specific people
  notFor: string; // Specific red flags for certain audiences
  suitability: GroupSuitability;
  sensitivity: ContentSensitivity;
  contentAdvisory: string; // Detailed description of problematic/sensitive elements
  lorePrerequisites: string; // Canon knowledge, easter eggs, previous movies required
  proTips: string;
}

export interface AnalysisData {
  general: GeneralInfo;
  friendliness: FriendlinessInfo;
  sources: { title: string; uri: string }[];
}

export interface MovieRecommendation {
  title: string;
  year: string;
  reason: string;
  suitability: string;
}

export interface LanguageGroup {
  language: string;
  movies: MovieRecommendation[];
}

export type AnalysisResult = 
  | { type: 'SUCCESS'; data: AnalysisData }
  | { type: 'AMBIGUOUS'; candidates: string[] }
  | { type: 'NOT_FOUND' };

export enum LoadingStage {
  IDLE = 'IDLE',
  SEARCHING = 'SEARCHING',
  ANALYZING = 'ANALYZING',
  RECOMMENDING = 'RECOMMENDING',
  MATCHING = 'MATCHING',
  COMPLETED = 'COMPLETED',
  ERROR = 'ERROR'
}

export interface RecommendationRequirements {
  genres: string[];
  company: string;
  pacing: string;
  languages: string[];
  customDescription: string;
}

export interface SimilarityRequest {
  sourceMovie: string;
  reason?: string;
}

