- If the title is AMBIGUOUS, provide a list of candidates.

STEP 2: DATA GATHERING
Search for factual data (cast, synopsis, trailer, streaming) and deep subjective analysis (reception, social friendliness).

STEP 3: SOCIAL ANALYSIS
You must evaluate the movie's "Group Friendliness" with extreme detail.
- friendlinessScore: (0-100)
- idealFor: Explain exactly which elements (themes, pacing, style) make it suited for specific types of people.
- notFor: Identify exactly who would find this a "red flag" or offensive (specific sensitive groups).
- lorePrerequisites: Detail if this movie requires knowledge of previous films, deep lore, canon, or if it has major easter eggs.
- sensitivity scores (0-10):
  - nuditySex: Physical intimacy/exposure.
  - violenceGore: Intensity and frequency of blood/injury.
  - profanity: Language intensity.
  - awkwardnessFactor: Specifically "cringe" moments with parents or dates.
  - pacingDrag: How likely it is to feel "boring" or "too long".
  - complexity: How confusing or hard to follow the plot is.
  - brainrot: Level of low-effort, chaotic, or nonsense "brainrot" humor/content.
- contentAdvisory: A thorough description of sensitive content including cultural insensitivity, offensive language, political subtext, or niche triggers.

You must return a JSON object matching the requested schema.`;

export const analyzeMovie = async (movieQuery: string, includeSpoilers: boolean): Promise<AnalysisResult> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analyze: "${movieQuery}". Spoilers: ${includeSpoilers}. Deep dive into social friendliness and lore required.`,
      config: {
        systemInstruction: ANALYSIS_SYSTEM_INSTRUCTION,
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            status: { type: Type.STRING, enum: ["SUCCESS", "AMBIGUOUS", "NOT_FOUND"] },
            candidates: { type: Type.ARRAY, items: { type: Type.STRING } },
            general: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                year: { type: Type.STRING },
                synopsis: { type: Type.STRING },
                director: { type: Type.STRING },
                actors: { type: Type.ARRAY, items: { type: Type.STRING } },
                musicScore: { type: Type.STRING },
                youtubeTrailerId: { type: Type.STRING },
                whereToWatch: { type: Type.ARRAY, items: { type: Type.STRING } }
              }
            },
            friendliness: {
              type: Type.OBJECT,
              properties: {
                friendlinessScore: { type: Type.NUMBER },
                overallReception: { type: Type.STRING },
                idealFor: { type: Type.STRING },
                notFor: { type: Type.STRING },
                lorePrerequisites: { type: Type.STRING },
                suitability: {
                  type: Type.OBJECT,
                  properties: {
                    familyWithKids: { type: Type.STRING },
                    firstDate: { type: Type.STRING },
                    cinephiles: { type: Type.STRING },
                    casualFriends: { type: Type.STRING }
                  }
                },
                sensitivity: {
                  type: Type.OBJECT,
                  properties: {
                    nuditySex: { type: Type.NUMBER },
                    violenceGore: { type: Type.NUMBER },
                    profanity: { type: Type.NUMBER },
                    awkwardnessFactor: { type: Type.NUMBER },
                    pacingDrag: { type: Type.NUMBER },
                    complexity: { type: Type.NUMBER },
                    brainrot: { type: Type.NUMBER }
                  }
                },
                contentAdvisory: { type: Type.STRING },
                proTips: { type: Type.STRING }
              }
            }
          }
        }
      },
    });

    const result = JSON.parse(response.text || "{}");

    if (result.status === "NOT_FOUND") return { type: 'NOT_FOUND' };
    if (result.status === "AMBIGUOUS") return { type: 'AMBIGUOUS', candidates: result.candidates || [] };

    const general = result.general || {
      title: movieQuery,
      year: "Unknown",
      synopsis: "No data available.",
      director: "Unknown",
      actors: [],
      musicScore: "N/A",
      youtubeTrailerId: "",
      whereToWatch: []
    };

    const friendliness = result.friendliness || {
      friendlinessScore: 0,
      overallReception: "No analysis available.",
      idealFor: "N/A",
      notFor: "N/A",
      lorePrerequisites: "No specific lore known.",
      suitability: { familyWithKids: "N/A", firstDate: "N/A", cinephiles: "N/A", casualFriends: "N/A" },
      sensitivity: { nuditySex: 0, violenceGore: 0, profanity: 0, awkwardnessFactor: 0, pacingDrag: 0, complexity: 0, brainrot: 0 },
      contentAdvisory: "N/A",
      proTips: "N/A"
    };

    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const sources = groundingChunks
      .map((chunk: any) => chunk.web ? { title: chunk.web.title, uri: chunk.web.uri } : null)
      .filter((s: any): s is { title: string; uri: string } => s !== null);

    return {
      type: 'SUCCESS',
      data: { general, friendliness, sources }
    };
  } catch (error) {
    console.error(error);
    throw error;
  }
};

