import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult, MovieRecommendation, LanguageGroup, RecommendationRequirements, SimilarityRequest } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const ANALYSIS_SYSTEM_INSTRUCTION = `
You are a world-class film critic and "social viewing" expert. Your task is to provide a surgical analysis of a movie for people planning a "movie night".

CRITICAL: SEARCH & IDENTIFICATION
- Use Google Search to find the EXACT movie release year, director, and lead cast. 
- DO NOT return "(Unknown)" or "Unknown" for the year if it is available on the web. 
- If the user provides a vague title (e.g., "The Host"), analyze if it's highly ambiguous. 
- If there are multiple famous movies with that name, return status "AMBIGUOUS" and list the candidates with their years.
- If one movie is overwhelmingly more famous, pick it but YOU MUST INCLUDE THE ACCURATE YEAR.
- If the movie doesn't exist, return "NOT_FOUND".

CRITICAL: SOCIAL ANALYSIS
Evaluate "Group Friendliness" with extreme precision:
1. friendlinessScore (0-100): Universal group safety.
2. idealFor: Specific elements (vibes, tropes, pacing) making it suited for a particular audience.
3. notFor: Clear RED FLAGS. Who should specifically avoid this.
4. lorePrerequisites: Does this require knowledge of previous films or deep lore?
5. Sensitivity Heatmap (0-10):
   - nuditySex, violenceGore, profanity, awkwardnessFactor, pacingDrag, complexity, brainrot, scaryIntensity, subtextRisk.
6. contentAdvisory: Detailed text description of ALL problematic elements.

You must return a valid JSON object.`;

export const analyzeMovie = async (movieQuery: string, includeSpoilers: boolean): Promise<AnalysisResult> => {
  try {
    const response = await ai.models.generateContent({
      // Upgraded to Pro for better grounding accuracy and adherence to strict metadata extraction
      model: 'gemini-3-pro-preview',
      contents: `Search and meticulously Analyze the movie: "${movieQuery}". Spoilers: ${includeSpoilers}. Ensure the release year is identified accurately.`,
      config: {
        systemInstruction: ANALYSIS_SYSTEM_INSTRUCTION,
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            status: { type: Type.STRING, enum: ["SUCCESS", "AMBIGUOUS", "NOT_FOUND"] },
            candidates: { type: Type.ARRAY, items: { type: Type.STRING } },
            general: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                year: { type: Type.STRING },
                synopsis: { type: Type.STRING },
                director: { type: Type.STRING },
                actors: { type: Type.ARRAY, items: { type: Type.STRING } },
                musicScore: { type: Type.STRING },
                youtubeTrailerId: { type: Type.STRING },
                whereToWatch: { type: Type.ARRAY, items: { type: Type.STRING } }
              }
            },
            friendliness: {
              type: Type.OBJECT,
              properties: {
                friendlinessScore: { type: Type.NUMBER },
                overallReception: { type: Type.STRING },
                idealFor: { type: Type.STRING },
                notFor: { type: Type.STRING },
                lorePrerequisites: { type: Type.STRING },
                suitability: {
                  type: Type.OBJECT,
                  properties: {
                    familyWithKids: { type: Type.STRING },
                    firstDate: { type: Type.STRING },
                    cinephiles: { type: Type.STRING },
                    casualFriends: { type: Type.STRING }
                  }
                },
                sensitivity: {
                  type: Type.OBJECT,
                  properties: {
                    nuditySex: { type: Type.NUMBER },
                    violenceGore: { type: Type.NUMBER },
                    profanity: { type: Type.NUMBER },
                    awkwardnessFactor: { type: Type.NUMBER },
                    pacingDrag: { type: Type.NUMBER },
                    complexity: { type: Type.NUMBER },
                    brainrot: { type: Type.NUMBER },
                    scaryIntensity: { type: Type.NUMBER },
                    subtextRisk: { type: Type.NUMBER }
                  }
                },
                contentAdvisory: { type: Type.STRING },
                proTips: { type: Type.STRING }
              }
            }
          }
        }
      },
    });

    const result = JSON.parse(response.text || "{}");

    if (result.status === "NOT_FOUND") return { type: 'NOT_FOUND' };
    if (result.status === "AMBIGUOUS") return { type: 'AMBIGUOUS', candidates: result.candidates || [] };

    const general = result.general || {
      title: movieQuery,
      year: "Unknown",
      synopsis: "No data available.",
      director: "Unknown",
      actors: [],
      musicScore: "N/A",
      youtubeTrailerId: "",
      whereToWatch: []
    };

    const friendliness = result.friendliness || {
      friendlinessScore: 0,
      overallReception: "No analysis available.",
      idealFor: "N/A",
      notFor: "N/A",
      lorePrerequisites: "No specific lore known.",
      suitability: { familyWithKids: "N/A", firstDate: "N/A", cinephiles: "N/A", casualFriends: "N/A" },
      sensitivity: { nuditySex: 0, violenceGore: 0, profanity: 0, awkwardnessFactor: 0, pacingDrag: 0, complexity: 0, brainrot: 0, scaryIntensity: 0, subtextRisk: 0 },
      contentAdvisory: "N/A",
      proTips: "N/A"
    };

    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const sources = groundingChunks
      .map((chunk: any) => chunk.web ? { title: chunk.web.title, uri: chunk.web.uri } : null)
      .filter((s: any): s is { title: string; uri: string } => s !== null);

    return {
      type: 'SUCCESS',
      data: { general, friendliness, sources }
