import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { AnalysisData } from '../types';

interface Message {
  role: 'user' | 'model';
  text: string;
}

interface CineChatProps {
  movieData: AnalysisData;
  onClose: () => void;
}

export const CineChat: React.FC<CineChatProps> = ({ movieData, onClose }) => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const chatInstance = useRef<any>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Initialize Chat Session with context
  useEffect(() => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const systemPrompt = `
      You are an expert film analyst at CineVault. You are chatting with a user about the movie: ${movieData.general.title} (${movieData.general.year}).

      HERE IS THE DATA FROM THE REPORT WE JUST GENERATED:
      - Synopsis: ${movieData.general.synopsis}
      - Director: ${movieData.general.director}
      - Main Cast: ${movieData.general.actors.join(', ')}
      - Friendliness Score: ${movieData.friendliness.friendlinessScore}/100
      - References & Prerequisites: ${movieData.friendliness.lorePrerequisites}
      - Sensitivity Heatmap: 
        Nudity: ${movieData.friendliness.sensitivity.nuditySex}/10, 
        Violence: ${movieData.friendliness.sensitivity.violenceGore}/10, 
        Profanity: ${movieData.friendliness.sensitivity.profanity}/10, 
        Awkwardness: ${movieData.friendliness.sensitivity.awkwardnessFactor}/10
      - Content Advisory: ${movieData.friendliness.contentAdvisory}
      - Expert Pro-Tip: ${movieData.friendliness.proTips}

      Your goal is to answer questions about this movie based on this data and your general knowledge. 
      Be concise, slightly witty, and help the user decide if they should watch it tonight.
      Never reveal spoilers unless the user specifically asks for them.
    `;

    chatInstance.current = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: systemPrompt,
      },
    });

    // Initial greeting
    setMessages([{ role: 'model', text: `Agent online. Any specific questions about "${movieData.general.title}" or our report findings?` }]);
  }, [movieData]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userMsg = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsLoading(true);

    try {
      const response = await chatInstance.current.sendMessage({ message: userMsg });
      const text = response.text;
      setMessages(prev => [...prev, { role: 'model', text: text }]);
    } catch (error) {
      console.error("Chat Error:", error);
      setMessages(prev => [...prev, { role: 'model', text: "Signal lost. My neural link to the database was interrupted. Try again?" }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 w-[350px] max-w-[calc(100vw-3rem)] h-[500px] max-h-[calc(100vh-10rem)] bg-cine-dark border border-gray-800 rounded-2xl shadow-2xl flex flex-col z-[100] animate-fade-in no-print overflow-hidden">
      {/* Header */}
      <div className="bg-cine-gray/50 p-4 border-b border-gray-800 flex justify-between items-center backdrop-blur-md">
        <div className="flex items-center gap-2">
          <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></div>
          <span className="text-[10px] font-black uppercase tracking-widest text-white">Cine-Chat: {movieData.general.title}</span>
        </div>
        <button onClick={onClose} className="text-gray-500 hover:text-white transition-colors">
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
          </svg>
        </button>
      </div>

      {/* Messages */}
      <div className="flex-grow overflow-y-auto p-4 space-y-4 scrollbar-hide">
        {messages.map((msg, idx) => (
          <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-3 rounded-xl text-xs leading-relaxed ${
              msg.role === 'user' 
                ? 'bg-cine-accent text-white rounded-br-none' 
                : 'bg-cine-gray/50 text-gray-200 border border-gray-800 rounded-bl-none'
            }`}>
              {msg.text}
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-cine-gray/50 text-gray-500 border border-gray-800 rounded-xl rounded-bl-none p-3 text-[10px] flex gap-1">
              <span className="animate-bounce">.</span>
              <span className="animate-bounce [animation-delay:0.2s]">.</span>
              <span className="animate-bounce [animation-delay:0.4s]">.</span>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input */}
      <form onSubmit={handleSend} className="p-4 bg-cine-black border-t border-gray-800 flex gap-2">
        <input 
          type="text" 
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="Ask about content, pacing, lore..."
          className="flex-grow bg-cine-dark border border-gray-800 rounded-lg px-3 py-2 text-xs text-white focus:outline-none focus:border-cine-accent"
          disabled={isLoading}
        />
        <button 
          type="submit" 
          disabled={isLoading || !input.trim()}
          className="bg-cine-accent hover:bg-red-600 text-white p-2 rounded-lg transition-colors disabled:opacity-50"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
